INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-dribble---the-playoff-edition-usa', 'Genesis', 'Double Dribble - The Playoff Edition (USA)', '1991', 'Platformer', 'Vic Tokai', '1', 'Action', 'Five-on-five basketball simulation with a TV-style presentation.', 'Win the playoff tournament by mastering the hardwood.', 'A classic Konami basketball title updated for 16-bit.', 'Double Dribble - The Playoff Edition features realistic basketball physics and signature dunks. Experience the drama of the 16-bit playoffs on your Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-robotniks-mean-bean-machine-europe', 'Genesis', 'Dr. Robotnik''s Mean Bean Machine (Europe)', '1993', 'Action', 'Alex Proyas', '1', 'Action', 'Falling-block puzzle game starring characters from Sonic.', 'Stack beans of the same color to clear them and defeat your opponent.', 'The Western localization of Puyo Puyo.', 'Dr. Robotnik''s Mean Bean Machine is an addictive 16-bit puzzle essential. Master chain reactions to send garbage beans to your rivals in this Sonic-themed hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-robotniks-mean-bean-machine-usa', 'Genesis', 'Dr. Robotnik''s Mean Bean Machine (USA)', '1994', 'Platformer', 'Visual Concepts', '2', 'Action', 'Falling-block puzzle game starring characters from Sonic.', 'Stack beans of the same color to clear them and defeat your opponent.', 'The North American release of the puzzle classic.', 'Dr. Robotnik''s Mean Bean Machine is an addictive 16-bit puzzle essential. Master chain reactions to send garbage beans to your rivals in this Sonic-themed hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-robotniks-mean-bean-machine-usa-beta', 'Genesis', 'Dr. Robotnik''s Mean Bean Machine (USA) (Beta)', '1992', 'Action', 'Electronic Arts', '1', 'Action', 'Falling-block puzzle game starring characters from Sonic.', 'Stack beans of the same color to clear them and defeat your opponent.', 'A beta development build of Mean Bean Machine.', 'See the early stages of a puzzle legend with the Mean Bean Machine Beta. A fascinating look at the development of this 16-bit Sega Genesis favorite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon---the-bruce-lee-story-europe', 'Genesis', 'Dragon - The Bruce Lee Story (Europe)', '1993', 'Shooter', 'Compile', '2', 'Shooter', 'One-on-one fighting game based on the life of Bruce Lee.', 'Fight through various opponents to fulfill your destiny.', 'A cinematic brawler celebrating the martial arts icon.', 'Dragon - The Bruce Lee Story offers fluid 16-bit combat. Master the "Jeet Kune Do" style and face your inner demons in this high-quality movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon---the-bruce-lee-story-usa', 'Genesis', 'Dragon - The Bruce Lee Story (USA)', '1992', 'Action', 'Opera House', '1', 'Action', 'One-on-one fighting game based on the life of Bruce Lee.', 'Fight through various opponents to fulfill your destiny.', 'The North American release of the Bruce Lee fighter.', 'Dragon - The Bruce Lee Story offers fluid 16-bit combat. Master the "Jeet Kune Do" style and face your inner demons in this high-quality movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---buyuu-retsuden-japan', 'Genesis', 'Dragon Ball Z - Buyuu Retsuden (Japan)', '1992', 'Action', 'Unlicensed', '2', 'Action', 'One-on-one fighting game featuring the Z-fighters.', 'Battle through the tournament to become the universe''s strongest.', 'The premier Dragon Ball Z game for the Mega Drive.', 'Dragon Ball Z - Buyuu Retsuden features high-speed aerial combat and energy blasts. Experience the iconic anime battles in this polished 16-bit Japanese fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---lappel-du-destin-france', 'Genesis', 'Dragon Ball Z - L''Appel du Destin (France)', '1990', 'Action', 'Titus Interactive', '1', 'Action', 'One-on-one fighting game featuring the Z-fighters.', 'Battle through the tournament to become the universe''s strongest.', 'The French release of the DBZ fighting game.', 'Dragon Ball Z - L''Appel du Destin brings Goku and Vegeta to the Mega Drive. Master the "Kamehameha" in this rare and sought-after European anime brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---lappel-du-destin-france-en-by-dbzgame-v095a-incomplete', 'Genesis', 'Dragon Ball Z - L''Appel du Destin (France) [En by DBZGame v0.95a] (Incomplete)', '1993', 'Sports', 'Sports Simulation', '2', 'Sports', 'One-on-one fighting game featuring the Z-fighters.', 'Battle through the tournament to become the universe''s strongest.', 'An English fan translation of the French DBZ game.', 'Experience the French Dragon Ball Z classic in English! This 16-bit translation makes the story and special moves accessible for a global audience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-slayer---eiyuu-densetsu-japan', 'Genesis', 'Dragon Slayer - Eiyuu Densetsu (Japan)', '1994', 'Sports', 'Dino Dini', '2', 'Sports', 'Traditional turn-based RPG with an epic fantasy narrative.', 'Lead Prince Logan on a quest to stop a growing darkness.', 'The first entry in the acclaimed Dragon Slayer series.', 'Dragon Slayer - Eiyuu Densetsu (The Legend of Heroes) is a 16-bit RPG landmark. Experience a deep story and classic turn-based combat on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-slayer---eiyuu-densetsu-ii-japan', 'Genesis', 'Dragon Slayer - Eiyuu Densetsu II (Japan)', '1994', 'Fighting', 'Unlicensed', '2', 'Fighting', 'Expanded turn-based RPG with deeper mechanics and story.', 'Follow a new generation of heroes to save the world of Iselhasa.', 'The massive sequel to the first Dragon Slayer.', 'Dragon Slayer - Eiyuu Densetsu II offers one of the largest RPG experiences on the Mega Drive. Master new magic systems and explore a vast 16-bit fantasy world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragons-eye-plus---shanghai-iii-japan', 'Genesis', 'Dragon''s Eye Plus - Shanghai III (Japan)', '1991', 'Platformer', 'Sega', '1', 'Action', 'Tile-matching puzzle game based on the classic Shanghai.', 'Clear the board by matching pairs of identical mahjong tiles.', 'A polished 16-bit mahjong simulation.', 'Dragon''s Eye Plus - Shanghai III brings classic tile-matching to your console. Enjoy multiple modes and high-quality 16-bit visuals in this relaxing puzzle game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragons-fury-usa-europe', 'Genesis', 'Dragon''s Fury (USA, Europe)', '1994', 'Adventure', 'Capcom', '1', 'Adventure', 'Dark fantasy-themed pinball with interactive boss battles.', 'Hit targets and complete missions to defeat the dragon.', 'A cult classic 16-bit pinball game (Devil''s Crush).', 'Dragon''s Fury is legendary for its occult atmosphere and addictive gameplay. Experience one of the best 16-bit pinball tables ever designed on your Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragons-revenge-usa-europe', 'Genesis', 'Dragon''s Revenge (USA, Europe)', '1994', 'Action', 'Mermaid Studios', '2', 'Action', 'Expanded fantasy pinball with multiple tables and story elements.', 'Journey through a dark world to defeat an evil sorceress.', 'The action-packed sequel to Dragon''s Fury.', 'Dragon''s Revenge adds more variety and boss-heavy action to the 16-bit pinball formula. Battle monsters across diverse tables in this high-energy Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dream-team-usa-japan', 'Genesis', 'Dream Team USA (Japan)', '1994', 'Compilation', 'Disney Interactive', '1', 'Compilation', 'Olympic-style sports game featuring the 1992 US basketball team.', 'Lead the "Dream Team" to Olympic gold through various matches.', 'A sports title celebrating the legendary 1992 US team.', 'Dream Team USA captures the hype of the 1992 Olympics. Experience 16-bit basketball with the biggest stars of the era in this unique Japanese sports game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drop-dash-in-sonic-2', 'Genesis', 'Drop Dash in Sonic 2', '1994', 'Action', 'Unlicensed', '1', 'Action', 'High-speed platforming with the modern "Drop Dash" ability.', 'Blitz through Sonic 2 stages with improved speed retention.', 'A mechanical mod bringing the Mania move to Sonic 2.', 'Drop Dash in Sonic 2 changes the game. Use Sonic''s newest signature move to maintain momentum in this modernized 16-bit classic experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drop-dash-in-sonic-3-&-knuckles', 'Genesis', 'Drop Dash in Sonic 3 & Knuckles', '1990', 'Fighting', 'Kaneko', '2', 'Fighting', 'High-speed platforming with the modern "Drop Dash" ability.', 'Blitz through the definitive Sonic game with new move physics.', 'A mechanical mod bringing the Mania move to Sonic 3.', 'Experience Sonic 3 & Knuckles like never before. The addition of the Drop Dash makes this 16-bit masterpiece feel faster and more fluid than ever.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dune---kampf-um-den-wustenplaneten-germany', 'Genesis', 'Dune - Kampf um den Wustenplaneten (Germany)', '1990', 'Fighting', 'Kaneko', '2', 'Fighting', 'Real-time strategy game with base building and spice mining.', 'Lead the Atreides, Ordos, or Harkonnen to total control of Arrakis.', 'The German version of the pioneer of console RTS.', 'Dune - Kampf um den Wustenplaneten is a 16-bit strategic triumph. Command armies and manage resources in the first great RTS for the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dune---the-battle-for-arrakis-usa', 'Genesis', 'Dune - The Battle for Arrakis (USA)', '1990', 'Fighting', 'Kaneko', '2', 'Fighting', 'Real-time strategy game with base building and spice mining.', 'Lead the Atreides, Ordos, or Harkonnen to total control of Arrakis.', 'The definitive 16-bit real-time strategy masterpiece.', 'Dune - The Battle for Arrakis (Dune II) set the standard for console RTS. Master the desert sands, harvest spice, and crush your enemies in this iconic Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dune-ii---the-battle-for-arrakis-europe', 'Genesis', 'Dune II - The Battle for Arrakis (Europe)', '1992', 'Puzzle', 'Aspect', '1', 'Puzzle', 'Real-time strategy with base building and unit management.', 'Conquer Arrakis by harvesting spice and defeating rival houses.', 'The European release of the pioneering console RTS.', 'Dune II - The Battle for Arrakis defined the RTS genre on consoles. Lead your house to victory through tactical 16-bit warfare and resource management on the Sega Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dungeons-&-dragons---warriors-of-the-eternal-sun-usa-europe', 'Genesis', 'Dungeons & Dragons - Warriors of the Eternal Sun (USA, Europe)', '1992', 'Action', 'Sega', '1', 'Action', 'Hybrid of top-down exploration and first-person dungeon crawling.', 'Explore the Hollow World to save your party from a mysterious force.', 'A deep and official D&D RPG for the Sega Genesis.', 'Dungeons & Dragons: Warriors of the Eternal Sun offers a unique RPG experience. Master tactical 16-bit combat and uncover ancient secrets in the legendary D&D universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dyna-brothers-japan', 'Genesis', 'Dyna Brothers (Japan)', '1993', 'Strategy', 'Sega', '2', 'Strategy', 'Real-time strategy and god-sim featuring dinosaurs.', 'Protect your dinosaur tribe from alien invaders and environmental threats.', 'A quirky and colorful Japanese strategy game.', 'Dyna Brothers brings a unique twist to 16-bit strategy. Manage your dinosaur ecosystem and repel invaders in this charming and innovative Mega Drive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dyna-brothers-2-japan', 'Genesis', 'Dyna Brothers 2 (Japan)', '1994', 'Strategy', 'Sega', '2', 'Strategy', 'Expanded strategy with more dinosaur types and deeper mechanics.', 'Lead your dinosaur army across diverse maps to defeat the aliens.', 'The refined and feature-rich sequel to Dyna Brothers.', 'Dyna Brothers 2 offers deeper tactical layers and improved visuals. Experience the peak of dinosaur-themed 16-bit strategy on the Japanese Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynamite-duke-world', 'Genesis', 'Dynamite Duke (World)', '1989', 'Action', 'Sega', '2', 'Action', 'Crosshair-based shooter with a semi-3D perspective and brawling.', 'Blast through enemy bases to stop a terrorist organization.', 'A high-octane arcade port with unique perspective shooting.', 'Dynamite Duke combines 16-bit shooting and punching. Take down mechanical bosses and clear enemy waves in this explosive and gritty Sega Genesis action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynamite-duke-world-alt', 'Genesis', 'Dynamite Duke (World) (Alt)', '1989', 'Action', 'Sega', '2', 'Action', 'Crosshair-based shooter with a semi-3D perspective and brawling.', 'Blast through enemy bases to stop a terrorist organization.', 'An alternate version of the crosshair-shooter port.', 'Dynamite Duke combines 16-bit shooting and punching. Take down mechanical bosses and clear enemy waves in this explosive and gritty Sega Genesis action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynamite-headdy-japan', 'Genesis', 'Dynamite Headdy (Japan)', '1994', 'Platformer', 'Treasure', '1', 'Action', 'Side-scrolling platformer with an interchangeable head mechanic.', 'Defeat the evil puppet Dark Demon to save the puppet world.', 'A visually spectacular and creative Treasure masterpiece.', 'Dynamite Headdy is a showcase of 16-bit technical power. Use 17 different power-up heads to solve puzzles and defeat bosses in this incredibly imaginative Sega game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynamite-headdy-japan-beta', 'Genesis', 'Dynamite Headdy (Japan) (Beta)', '1994', 'Platformer', 'Treasure', '1', 'Action', 'Side-scrolling platformer with an interchangeable head mechanic.', 'Defeat the evil puppet Dark Demon to save the puppet world.', 'A beta development version of the Treasure classic.', 'See the early puppet-based combat in the Dynamite Headdy Beta. A fascinating look at the development of one of the most creative 16-bit platformers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynamite-headdy-japan-en-by-mijet-v20070428', 'Genesis', 'Dynamite Headdy (Japan) [En by MIJET v20070428]', '1994', 'Platformer', 'Treasure', '1', 'Action', 'Side-scrolling platformer with an interchangeable head mechanic.', 'Defeat the evil puppet Dark Demon to save the puppet world.', 'An English fan translation of the original Japanese version.', 'Play the original Dynamite Headdy with its intended difficulty and story. This 16-bit translation restores the Japanese dialogue and visual details for Mega Drive fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynamite-headdy-usa-europe', 'Genesis', 'Dynamite Headdy (USA, Europe)', '1994', 'Platformer', 'Treasure', '1', 'Action', 'Side-scrolling platformer with an interchangeable head mechanic.', 'Defeat the evil puppet Dark Demon to save the puppet world.', 'The North American/European release of the Treasure hit.', 'Dynamite Headdy is a masterpiece of 16-bit animation. Swap heads to gain unique abilities and battle through colorful, stage-themed levels in this Sega Genesis essential.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ea-hockey-europe', 'Genesis', 'EA Hockey (Europe)', '1991', 'Sports', 'Electronic Arts', '2', 'Sports', 'Professional ice hockey simulation with high-speed arcade play.', 'Lead your team to the cup by mastering the ice and checking.', 'The European debut of EA''s legendary hockey engine.', 'EA Hockey (NHL Hockey) set the standard for 16-bit sports games. Experience smooth skating and intense 16-bit action in this quintessential Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ea-sports-double-header-europe', 'Genesis', 'EA Sports Double Header (Europe)', '1991', 'Sports', 'Electronic Arts', '2', 'Sports', 'A compilation of two classic EA Sports titles on one cart.', 'Compete in both professional football and ice hockey.', 'A "2-in-1" sports pack featuring John Madden and NHL.', 'EA Sports Double Header offers the best of the 16-bit gridiron and ice. Enjoy two legendary sports simulations on a single Sega Genesis cartridge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earnest-evans-usa', 'Genesis', 'Earnest Evans (USA)', '1991', 'Action', 'Wolf Team', '1', 'Action', 'Side-scrolling action-adventure with a physics-based protagonist.', 'Help Earnest recover ancient idols and stop an evil cult.', 'A unique 16-bit adventure with multi-jointed sprites.', 'Earnest Evans features distinct animation and challenging platforming. Explore ancient ruins and battle occult forces in this cult classic Sega action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earth-defense-usa-unl', 'Genesis', 'Earth Defense (USA) (Unl)', '1994', 'Shooter', 'Unlicensed', '2', 'Shooter', 'Top-down shoot ''em up with a focus on global defense.', 'Protect the Earth from waves of alien spacecraft.', 'An unlicensed vertical shooter for the Mega Drive.', 'Earth Defense delivers high-speed 16-bit shooting action. Battle through multiple stages and defeat massive bosses in this rare and challenging unlicensed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-europe', 'Genesis', 'Earthworm Jim (Europe)', '1994', 'Platformer', 'Shiny Entertainment', '1', 'Action', 'Surreal side-scrolling platformer with run-and-gun elements.', 'Rescue Princess What''s-Her-Name and defeat Psy-Crow.', 'An iconic 16-bit action game with hand-drawn animation.', 'Earthworm Jim is a masterpiece of humor and design. Use Jim as a whip and blast through weird worlds in this visually stunning and quirky Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-usa', 'Genesis', 'Earthworm Jim (USA)', '1994', 'Platformer', 'Shiny Entertainment', '1', 'Action', 'Surreal side-scrolling platformer with run-and-gun elements.', 'Rescue Princess What''s-Her-Name and defeat Psy-Crow.', 'The North American release of the legendary Jim.', 'Earthworm Jim is a masterpiece of humor and design. Use Jim as a whip and blast through weird worlds in this visually stunning and quirky Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-2-europe', 'Genesis', 'Earthworm Jim 2 (Europe)', '1995', 'Platformer', 'Shiny Entertainment', '2', 'Action', 'Multi-genre platformer featuring bizarre mini-games and action.', 'Journey through Jim''s surreal mind to find the Golden Udder.', 'The high-energy and creative sequel to Earthworm Jim.', 'Earthworm Jim 2 pushes the 16-bit limits with variety. From cow-tossing to isometric shooting, experience the ultimate in 16-bit cartoon chaos on the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-2-usa', 'Genesis', 'Earthworm Jim 2 (USA)', '1995', 'Platformer', 'Shiny Entertainment', '2', 'Action', 'Multi-genre platformer featuring bizarre mini-games and action.', 'Journey through Jim''s surreal mind to find the Golden Udder.', 'The North American release of the wacky sequel.', 'Earthworm Jim 2 pushes the 16-bit limits with variety. From cow-tossing to isometric shooting, experience the ultimate in 16-bit cartoon chaos on the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecco---the-tides-of-time-europe', 'Genesis', 'Ecco - The Tides of Time (Europe)', '1994', 'Action', 'Novotrade', '1', 'Adventure', 'Non-linear underwater adventure with complex physics and story.', 'Travel through time to save the oceans and the future.', 'The atmospheric and challenging sequel to Ecco.', 'Ecco: The Tides of Time offers breathtaking 16-bit visuals and a haunting story. Master the sonar and swim through beautiful, dangerous waters in this Sega epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecco---the-tides-of-time-usa', 'Genesis', 'Ecco - The Tides of Time (USA)', '1994', 'Action', 'Novotrade', '1', 'Adventure', 'Non-linear underwater adventure with complex physics and story.', 'Travel through time to save the oceans and the future.', 'The North American release of the Ecco sequel.', 'Ecco: The Tides of Time offers breathtaking 16-bit visuals and a haunting story. Master the sonar and swim through beautiful, dangerous waters in this Sega epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecco---the-tides-of-time-usa-beta', 'Genesis', 'Ecco - The Tides of Time (USA) (Beta)', '1994', 'Action', 'Novotrade', '1', 'Adventure', 'Non-linear underwater adventure with complex physics and story.', 'Travel through time to save the oceans and the future.', 'A beta development version of The Tides of Time.', 'Explore the early depths of the Ecco sequel in this beta. A fascinating look at the development of the 16-bit aquatic physics and level designs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecco-jr-usa-australia-february-1995', 'Genesis', 'Ecco Jr. (USA, Australia) (February 1995)', '1995', 'Platformer', 'Novotrade', '1', 'Action', 'Educational exploration game designed for younger players.', 'Complete simple tasks and learn about ocean life as baby Ecco.', 'A kid-friendly entry in the Ecco the Dolphin series.', 'Ecco Jr. makes the beautiful 16-bit ocean accessible to everyone. Explore at your own pace and meet sea friends in this gentle and colorful Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecco-jr-usa-australia-march-1995', 'Genesis', 'Ecco Jr. (USA, Australia) (March 1995)', '1995', 'Platformer', 'Novotrade', '1', 'Action', 'Educational exploration game designed for younger players.', 'Complete simple tasks and learn about ocean life as baby Ecco.', 'An alternate build of the kid-friendly Ecco title.', 'Ecco Jr. makes the beautiful 16-bit ocean accessible to everyone. Explore at your own pace and meet sea friends in this gentle and colorful Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecco-the-dolphin-japan', 'Genesis', 'Ecco the Dolphin (Japan)', '1992', 'Action', 'Novotrade', '1', 'Adventure', 'Atmospheric underwater exploration and puzzle-solving.', 'Rescue your pod from a mysterious alien abduction.', 'The Japanese Mega Drive version of the dolphin classic.', 'Ecco the Dolphin is a landmark of 16-bit atmosphere. Use sonar to communicate and solve complex puzzles in this beautiful and difficult Sega masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecco-the-dolphin-usa-europe', 'Genesis', 'Ecco the Dolphin (USA, Europe)', '1992', 'Action', 'Novotrade', '1', 'Adventure', 'Atmospheric underwater exploration and puzzle-solving.', 'Rescue your pod from a mysterious alien abduction.', 'The definitive 16-bit aquatic adventure for Genesis.', 'Ecco the Dolphin is a landmark of 16-bit atmosphere. Use sonar to communicate and solve complex puzzles in this beautiful and difficult Sega masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecco-the-dolphin-ii-japan', 'Genesis', 'Ecco the Dolphin II (Japan)', '1994', 'Action', 'Novotrade', '1', 'Adventure', 'Non-linear underwater adventure with complex physics and story.', 'Travel through time to save the oceans and the future.', 'The Japanese Mega Drive version of The Tides of Time.', 'Ecco the Dolphin II (Tides of Time) expands on the original with new transformations and 3D-style stages. Experience a pinnacle of 16-bit storytelling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eggman-the-dictator-in-sonic-the-hedgehog', 'Genesis', 'Eggman the Dictator in Sonic the Hedgehog', '1994', 'Action', 'Unlicensed', '1', 'Action', 'High-speed platforming with Eggman as the central figure.', 'Take over South Island by defeating the local heroes.', 'A character-swap mod starring the villainous Eggman.', 'Eggman the Dictator puts you in the pilot''s seat. Navigate the original 16-bit Sonic levels with the Doctor''s unique physics and mechanical flair.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('el-viento-japan', 'Genesis', 'El Viento (Japan)', '1991', 'Action', 'Alfa System', '1', 'Action', 'Side-scrolling action platformer set in a 1920s fantasy world.', 'Prevent the resurrection of Hastur and save New York City.', 'A fast-paced and stylish action game from Wolf Team.', 'El Viento features cinematic story sequences and explosive 16-bit combat. Control Annet and use boomerangs and magic to fight cultists on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('el-viento-usa', 'Genesis', 'El Viento (USA)', '1991', 'Action', 'Alfa System', '1', 'Action', 'Side-scrolling action platformer set in a 1920s fantasy world.', 'Prevent the resurrection of Hastur and save New York City.', 'The North American release of the cinematic action game.', 'El Viento features cinematic story sequences and explosive 16-bit combat. Control Annet and use boomerangs and magic to fight cultists on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elemental-master-japan', 'Genesis', 'Elemental Master (Japan)', '1990', 'Shooter', 'Technosoft', '1', 'Shooter', 'Vertical-scrolling shoot ''em up with elemental magic.', 'Use five elemental spells to defeat the Gyra army.', 'A high-fantasy shmup with incredible music and art.', 'Elemental Master is a unique fantasy shooter from TechnoSoft. Master fire, wind, and lightning to battle through beautiful 16-bit environments on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elemental-master-usa', 'Genesis', 'Elemental Master (USA)', '1990', 'Shooter', 'Technosoft', '1', 'Shooter', 'Vertical-scrolling shoot ''em up with elemental magic.', 'Use five elemental spells to defeat the Gyra army.', 'The North American version of the fantasy shooter.', 'Elemental Master is a unique fantasy shooter from TechnoSoft. Master fire, wind, and lightning to battle through beautiful 16-bit environments on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elf-wor-china-unl', 'Genesis', 'Elf Wor (China) (Unl)', '1991', 'Platformer', 'Unlicensed', '1', 'Action', 'Side-scrolling action with exploration and projectile combat.', 'Defeat waves of undead and supernatural threats to clear stages.', 'An unlicensed action game also known as Super Magician.', 'Elf Wor (Ling Huan Daoshi) brings Eastern supernatural horror to the Genesis. Battle through 16-bit levels filled with ghosts and demons in this rare unlicensed action-platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eliminate-down-japan', 'Genesis', 'Eliminate Down (Japan)', '1993', 'Shooter', 'Aprinet', '1', 'Shooter', 'Horizontal-scrolling shoot ''em up with three swappable weapon types.', 'Pilot the Steel Pyron and stop the Amuleto alien invasion.', 'One of the rarest and most intense 16-bit shmups.', 'Eliminate Down is a technical masterpiece for the Mega Drive. Master its unique three-way weapon system and survive eight levels of brutal, high-speed 16-bit shooting action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elitserien-95-sweden', 'Genesis', 'Elitserien 95 (Sweden)', '1995', 'Sports', 'Sega', '2', 'Sports', 'Professional ice hockey simulation with updated Swedish rosters.', 'Lead your favorite Swedish team to the Elitserien championship.', 'The 1995 edition of the Swedish Elite League hockey series.', 'Elitserien 95 brings the intensity of Swedish hockey to the Genesis. Featuring authentic teams and refined 16-bit EA Sports gameplay, it''s a must-play for hockey fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elitserien-96-sweden', 'Genesis', 'Elitserien 96 (Sweden)', '1996', 'Sports', 'Sega', '2', 'Sports', 'Professional ice hockey simulation with updated Swedish rosters.', 'Lead your favorite Swedish team to the Elitserien championship.', 'The 1996 edition of the Swedish Elite League hockey series.', 'Elitserien 96 offers the definitive 16-bit Swedish hockey experience. Enjoy updated rosters and the classic EA Sports engine on your Sega Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emerald-the-hedgehog-12345-in-sonic-2!', 'Genesis', 'Emerald The Hedgehog 12345 In Sonic 2!', '1994', 'Platformer', 'Hack', '1', 'Action', 'High-speed platforming starring a custom green hedgehog.', 'Complete the Sonic 2 campaign with a new emerald-themed aesthetic.', 'A popular 5-in-1 character modification for Sonic 2.', 'Emerald The Hedgehog in Sonic 2 gives the classic sequel a fresh look. Play as the vibrant green hero and experience the legendary 16-bit speed with a new twist.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('empire-of-steel-europe', 'Genesis', 'Empire of Steel (Europe)', '1992', 'Shooter', 'Hot-B', '1', 'Shooter', 'Horizontal-scrolling shoot ''em up with a steampunk aesthetic.', 'Pilot a zeppelin to save the world from the Zenn Empire.', 'A beautifully stylized steampunk shooter (Steel Empire).', 'Empire of Steel is a 16-bit visual treat. Choose between a nimble plane or a heavy zeppelin and blast through unique steampunk levels in this Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-baseball-tonight-usa', 'Genesis', 'ESPN Baseball Tonight (USA)', '1994', 'Sports', 'Sony Imagesoft', '2', 'Sports', 'Professional baseball simulation with an ESPN-style presentation.', 'Win the World Series while navigating deep season and stat modes.', 'A realistic baseball sim with authentic ESPN branding.', 'ESPN Baseball Tonight delivers the atmosphere of the big leagues. Master 16-bit pitching and batting in this detailed and professionally presented sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-national-hockey-night-usa', 'Genesis', 'ESPN National Hockey Night (USA)', '1994', 'Sports', 'Sony Imagesoft', '2', 'Sports', 'Professional ice hockey simulation with ESPN broadcast flair.', 'Lead your team through the season to win the Stanley Cup.', 'A gritty hockey sim featuring the "National Hockey Night" brand.', 'ESPN National Hockey Night brings the broadcast experience home. Enjoy hard-hitting 16-bit hockey action and deep season play on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-national-hockey-night-usa-beta', 'Genesis', 'ESPN National Hockey Night (USA) (Beta)', '1994', 'Sports', 'Sony Imagesoft', '2', 'Sports', 'Professional ice hockey simulation with ESPN broadcast flair.', 'Lead your team through the season to win the Stanley Cup.', 'A beta development build of the ESPN hockey title.', 'Peek behind the development of 16-bit sports with the ESPN National Hockey Night Beta. Experience early gameplay tweaks for this authentic hockey sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-speed-world-usa', 'Genesis', 'ESPN Speed World (USA)', '1994', 'Racing', 'Sony Imagesoft', '2', 'Racing', 'High-speed stock car racing with an ESPN presentation.', 'Master various tracks to win the Speed World racing championship.', 'An arcade-style stock car racer with ESPN branding.', 'ESPN Speed World features fast-paced 16-bit racing and professional commentary. Manage your pit stops and out-drive the competition in this intense Sega racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-speed-world-usa-beta', 'Genesis', 'ESPN Speed World (USA) (Beta)', '1994', 'Racing', 'Sony Imagesoft', '2', 'Racing', 'High-speed stock car racing with an ESPN presentation.', 'Master various tracks to win the Speed World racing championship.', 'A beta development build of the ESPN racing title.', 'Experience the early tuning of 16-bit stock car racing in the ESPN Speed World Beta. See how this high-speed Sega title was built for the professional circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-sunday-night-nfl-usa', 'Genesis', 'ESPN Sunday Night NFL (USA)', '1994', 'Sports', 'Sony Imagesoft', '2', 'Sports', 'Professional American football simulation with Sunday night flair.', 'Lead your team to the Super Bowl through a full NFL season.', 'A broadcast-style football sim with ESPN branding.', 'ESPN Sunday Night NFL brings the excitement of prime-time football to the Genesis. Master 16-bit play-calling and execute the perfect drive in this sports classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-sunday-night-nfl-usa-beta', 'Genesis', 'ESPN Sunday Night NFL (USA) (Beta)', '1994', 'Sports', 'Sony Imagesoft', '2', 'Sports', 'Professional American football simulation with Sunday night flair.', 'Lead your team to the Super Bowl through a full NFL season.', 'A beta development build of the ESPN football title.', 'Discover the development process of 16-bit football in the ESPN Sunday Night NFL Beta. Explore early playbooks and mechanics for this Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eswat---city-under-siege-usa', 'Genesis', 'ESWAT - City Under Siege (USA)', '1990', 'Action', 'Sega', '1', 'Action', 'Side-scrolling action platformer with futuristic police armor.', 'Defeat the high-tech crime syndicate as a cybernetically enhanced cop.', 'The North American release of the iconic ESWAT brawler.', 'ESWAT: City Under Siege delivers gritty 16-bit justice. Upgrade your gear and take down massive mechanical bosses in this quintessential Sega action masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eternal-champions-europe', 'Genesis', 'Eternal Champions (Europe)', '1993', 'Fighting', 'Sega', '2', 'Fighting', 'One-on-one fighting game with "Overkill" finishing moves.', 'Win the tournament to save history and avoid your own death.', 'A deep and violent fighting game with time-traveling warriors.', 'Eternal Champions is one of the most ambitious fighters on the Genesis. Master complex moves and environmental fatalities in this dark and cinematic 16-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eternal-champions-europe-beta', 'Genesis', 'Eternal Champions (Europe) (Beta)', '1993', 'Fighting', 'Sega', '2', 'Fighting', 'One-on-one fighting game with "Overkill" finishing moves.', 'Win the tournament to save history and avoid your own death.', 'A beta development build of the Sega fighting classic.', 'Explore the early combat balance of the Eternal Champions Beta. A fascinating look at the creation of this 16-bit fighting legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eternal-champions-japan', 'Genesis', 'Eternal Champions (Japan)', '1993', 'Fighting', 'Sega', '2', 'Fighting', 'One-on-one fighting game with "Overkill" finishing moves.', 'Win the tournament to save history and avoid your own death.', 'The Japanese Mega Drive release of Eternal Champions.', 'Eternal Champions brings its unique "Inner Strength" system to the Mega Drive. Fight through history and master 16-bit martial arts in this high-quality fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eternal-champions-usa', 'Genesis', 'Eternal Champions (USA)', '1993', 'Fighting', 'Sega', '2', 'Fighting', 'One-on-one fighting game with "Overkill" finishing moves.', 'Win the tournament to save history and avoid your own death.', 'The North American release of the legendary Sega fighter.', 'Eternal Champions is a masterpiece of 16-bit combat. Master the unique styles of nine warriors and change the course of history on your Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('europa-sensen-japan', 'Genesis', 'Europa Sensen (Japan)', '1991', 'Action', 'Telenet Japan', '1', 'Action', 'Grand strategy and tactical combat set during World War II.', 'Lead your forces to victory across the European and African fronts.', 'The Japanese version of Operation Europe: Path to Victory.', 'Europa Sensen offers deep 16-bit military strategy. Manage generals, resources, and tactical troop movements in this massive WWII simulation by Koei.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('european-club-soccer-europe', 'Genesis', 'European Club Soccer (Europe)', '1992', 'Sports', 'Dynamix', '2', 'Sports', 'Soccer simulation featuring top European clubs and leagues.', 'Lead your favorite club to victory in the European Cup.', 'A comprehensive soccer title known as World Cup Soccer in the US.', 'European Club Soccer offers fast-paced 16-bit football. Master the pitch with dozens of teams and intuitive controls in this polished Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('evander-holyfields-real-deal-boxing-world', 'Genesis', 'Evander Holyfield''s ''Real Deal'' Boxing (World)', '1992', 'Sports', 'Gray Matter', '2', 'Sports', 'One-on-one boxing simulation with the "Real Deal" engine.', 'Rise through the ranks to become the undisputed heavyweight champion.', 'A highly acclaimed boxing game featuring Evander Holyfield.', 'Evander Holyfield''s ''Real Deal'' Boxing is the gold standard for 16-bit pugilism. Create your own fighter and master the ring in this deep and realistic sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ex-mutants-usa-europe', 'Genesis', 'Ex-Mutants (USA, Europe)', '1992', 'Action', 'Data East', '1', 'Action', 'Side-scrolling action-platformer based on the Malibu comic.', 'Rescue your captured team members and stop the villainous Sluggo.', 'A gritty brawler with weapon-based combat and exploration.', 'Ex-Mutants brings the post-apocalyptic comic to life. Choose between Ackroyd or Shannon and fight through 16-bit mutant hordes in this challenging Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ex-ranza-japan', 'Genesis', 'Ex-Ranza (Japan)', '1991', 'Action', 'NCS', '1', 'Action', 'Hybrid of side-scrolling platforming and directional shooting.', 'Pilot a highly mobile mech to destroy the Rahuna invaders.', 'A technical marvel with incredible physics (Ranger X).', 'Ex-Ranza (Ranger X) is one of the most impressive games on the Genesis. Control your mech and support vehicle independently in this visually stunning 16-bit epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ex-ranza-japan-beta', 'Genesis', 'Ex-Ranza (Japan) (Beta)', '1991', 'Action', 'NCS', '1', 'Action', 'Hybrid of side-scrolling platforming and directional shooting.', 'Pilot a highly mobile mech to destroy the Rahuna invaders.', 'A beta development build of the technical masterpiece Ranger X.', 'See the early engine of a 16-bit legend in the Ex-Ranza Beta. Discover how the unique dual-control mechanics were refined for the final Sega release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('exile---toki-no-hazama-he-japan', 'Genesis', 'Exile - Toki no Hazama he (Japan)', '1991', 'RPG', 'Telenet Japan', '1', 'RPG', 'Action-RPG with platforming elements and a focus on storyline.', 'Travel between worlds to stop a magical conflict and find your way home.', 'A creative action-RPG known for its unique physics.', 'Exile (Toki no Hazama he) blends 16-bit platforming with deep RPG exploration. Experience an atmospheric story and challenging combat on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('exile-usa', 'Genesis', 'Exile (USA)', '1991', 'RPG', 'Telenet Japan', '1', 'RPG', 'Action-RPG with platforming elements and a focus on storyline.', 'Travel between worlds to stop a magical conflict and find your way home.', 'The North American localized version of the Exile RPG.', 'Exile offers a unique blend of overhead RPG exploration and side-scrolling 16-bit action. Navigate a complex plot and survive dangerous realms on the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('exo-squad-europe', 'Genesis', 'Exo Squad (Europe)', '1995', 'Action', 'Novotrade', '1', 'Action', 'Multi-genre action game based on the sci-fi animated series.', 'Complete missions using E-frames to stop the Neosapien uprising.', 'A varied action title featuring flying and brawling stages.', 'Exo Squad captures the high-stakes drama of the cartoon. Master 16-bit mech combat and aerial dogfights in this ambitious and challenging Sega tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('exo-squad-usa', 'Genesis', 'Exo Squad (USA)', '1995', 'Action', 'Novotrade', '1', 'Action', 'Multi-genre action game based on the sci-fi animated series.', 'Complete missions using E-frames to stop the Neosapien uprising.', 'The North American release of the Exo Squad game.', 'Exo Squad captures the high-stakes drama of the cartoon. Master 16-bit mech combat and aerial dogfights in this ambitious and challenging Sega tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('exo-squad-usa-beta', 'Genesis', 'Exo Squad (USA) (Beta)', '1995', 'Action', 'Novotrade', '1', 'Action', 'Multi-genre action game based on the sci-fi animated series.', 'Complete missions using E-frames to stop the Neosapien uprising.', 'A beta development version of the Exo Squad title.', 'Explore the early mission designs of the Exo Squad Beta. A rare look at the development of this multi-faceted 16-bit action game for the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('exodus---journey-to-the-promised-land-usa-unl', 'Genesis', 'Exodus - Journey to the Promised Land (USA) (Unl)', '1994', 'Action', 'Wisdom Tree', '1', 'Adventure', 'Puzzle-platformer based on the biblical story of the Exodus.', 'Lead the Israelites to the Promised Land while solving puzzles.', 'A religious-themed unlicensed title by Wisdom Tree.', 'Exodus: Journey to the Promised Land features challenging 16-bit puzzles and action. Use your staff and logic to guide your people in this unique Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-117-night-storm-usa-europe', 'Genesis', 'F-117 Night Storm (USA, Europe)', '1993', 'Simulation', 'MicroProse', '1', 'Simulation', 'First-person flight simulation with mission-based stealth combat.', 'Complete classified bombing runs and air-to-air missions undetected.', 'A realistic stealth fighter sim with a cinematic flair.', 'F-117 Night Storm delivers high-stakes 16-bit aerial combat. Master stealth technology and precision strikes across various global theaters on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-117-stealth---operation-night-storm-japan', 'Genesis', 'F-117 Stealth - Operation Night Storm (Japan)', '1993', 'Simulation', 'MicroProse', '1', 'Simulation', 'First-person flight simulation with mission-based stealth combat.', 'Complete classified bombing runs and air-to-air missions undetected.', 'The Japanese Mega Drive version of the F-117 stealth sim.', 'F-117 Stealth: Operation Night Storm offers deep tactical flight simulation. Utilize advanced radar-jamming tech to complete dangerous 16-bit missions on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-15-strike-eagle-ii-europe', 'Genesis', 'F-15 Strike Eagle II (Europe)', '1991', 'Simulation', 'Sterling Silver', '1', 'Simulation', 'High-speed flight combat simulation with 3D wireframe environments.', 'Engage in dogfights and destroy ground targets in enemy territory.', 'A fast-paced and accessible flight combat simulator.', 'F-15 Strike Eagle II brings intense 16-bit dogfighting to the Genesis. Experience smooth 3D-style flight and explosive air combat in this MicroProse classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-15-strike-eagle-ii-usa', 'Genesis', 'F-15 Strike Eagle II (USA)', '1991', 'Simulation', 'Sterling Silver', '1', 'Simulation', 'High-speed flight combat simulation with 3D wireframe environments.', 'Engage in dogfights and destroy ground targets in enemy territory.', 'The North American release of the F-15 flight sim.', 'F-15 Strike Eagle II brings intense 16-bit dogfighting to the Genesis. Experience smooth 3D-style flight and explosive air combat in this MicroProse classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-15-strike-eagle-ii-usa-beta', 'Genesis', 'F-15 Strike Eagle II (USA) (Beta)', '1991', 'Simulation', 'MicroProse', '1', 'Simulation', 'High-speed flight combat simulation with 3D wireframe environments.', 'Engage in dogfights and destroy ground targets in enemy territory.', 'A beta development build of F-15 Strike Eagle II.', 'Explore the early flight physics of the F-15 Strike Eagle II Beta. A fascinating look at the creation of 16-bit 3D flight on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-22-interceptor-japan', 'Genesis', 'F-22 Interceptor (Japan)', '1991', 'Simulation', 'Electronic Arts', '1', 'Simulation', 'Modern jet fighter simulation with 3D polygon-style graphics.', 'Protect airspace and eliminate threats using advanced weaponry.', 'A technical flight simulator featuring the F-22 Raptor.', 'F-22 Interceptor is a milestone for 16-bit flight sims. Engage in realistic dogfights and manage your payload in this ambitious Mega Drive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-22-interceptor-usa-europe-june-1992', 'Genesis', 'F-22 Interceptor (USA, Europe) (June 1992)', '1992', 'Simulation', 'Electronic Arts', '1', 'Simulation', 'Modern jet fighter simulation with 3D polygon-style graphics.', 'Protect airspace and eliminate threats using advanced weaponry.', 'The June 1992 update of the Raptor flight sim.', 'F-22 Interceptor offers deep simulation mechanics and 3D perspectives. Master the cockpit and dominate the skies in this legendary 16-bit flight simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-22-interceptor-usa-europe-september-1991', 'Genesis', 'F-22 Interceptor (USA, Europe) (September 1991)', '1991', 'Simulation', 'Electronic Arts', '1', 'Simulation', 'Modern jet fighter simulation with 3D polygon-style graphics.', 'Protect airspace and eliminate threats using advanced weaponry.', 'The original September 1991 release of F-22 Interceptor.', 'F-22 Interceptor offers deep simulation mechanics and 3D perspectives. Master the cockpit and dominate the skies in this legendary 16-bit flight simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-22-interceptor-usa-beta', 'Genesis', 'F-22 Interceptor (USA) (Beta)', '1991', 'Simulation', 'Electronic Arts', '1', 'Simulation', 'Modern jet fighter simulation with 3D polygon-style graphics.', 'Protect airspace and eliminate threats using advanced weaponry.', 'A beta development version of the F-22 flight sim.', 'See how 3D flight was optimized for the Genesis in the F-22 Interceptor Beta. Explore early mission designs and cockpit controls in this 16-bit prototype.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1---world-championship-edition-europe', 'Genesis', 'F1 - World Championship Edition (Europe)', '1994', 'Racing', 'Traveller''s Tales', '2', 'Racing', 'High-speed Formula 1 racing with updated team rosters.', 'Win the F1 World Championship by mastering every track.', 'An enhanced and polished F1 racing simulation.', 'F1 - World Championship Edition offers blistering 16-bit speed. Experience refined handling and professional racing strategy in this definitive Sega racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1---world-championship-edition-europe-beta', 'Genesis', 'F1 - World Championship Edition (Europe) (Beta)', '1994', 'Racing', 'Traveller''s Tales', '2', 'Racing', 'High-speed Formula 1 racing with updated team rosters.', 'Win the F1 World Championship by mastering every track.', 'A beta version of the World Championship Edition.', 'Test the limits of 16-bit racing in the F1 - World Championship Edition Beta. A rare look at the tuning of this high-speed Sega racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-europe', 'Genesis', 'F1 (Europe)', '1993', 'Racing', 'Domark', '2', 'Racing', 'High-speed Formula 1 racing with a focus on realism.', 'Rise through the ranks to become the world''s best F1 driver.', 'A fast and fluid F1 racing game by Domark.', 'F1 brings the thrill of grand prix racing to the Genesis. Master pit stops and rainy tracks in this challenging and technical 16-bit racing sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-circus-md-japan', 'Genesis', 'F1 Circus MD (Japan)', '1994', 'Racing', 'Nihon System', '2', 'Racing', 'Top-down Formula 1 racing with a focus on team management.', 'Build a winning team and outdrive rivals on the F1 circuit.', 'A popular Japanese top-down racing sim.', 'F1 Circus MD combines racing action with deep 16-bit management. Optimize your car and master the curves in this stylish Mega Drive classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('faery-tale-adventure-the-usa-europe', 'Genesis', 'Faery Tale Adventure, The (USA, Europe)', '1994', 'RPG', 'Starting Line', '1', 'Adventure', 'Top-down open-world action RPG with a massive map.', 'Journey across a vast kingdom to find a lost talisman.', 'One of the largest and deepest RPGs on the system.', 'The Faery Tale Adventure features a massive 16-bit world to explore. Command three brothers on an epic quest in this early landmark of Sega Genesis RPGs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('family-feud-usa', 'Genesis', 'Family Feud (USA)', '1993', 'Trivia', 'GameTek', '2', 'Trivia', 'Digital board game based on the popular TV game show.', 'Answer survey questions to win points and prizes for your family.', 'A faithful 16-bit adaptation of the hit game show.', 'Play the classic show at home with Family Feud. Compete against the AI or friends in this fun and trivia-heavy 16-bit Sega Genesis title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantasia-world', 'Genesis', 'Fantasia (World)', '1991', 'Platformer', 'Sega', '1', 'Platformer', 'Side-scrolling platformer based on the Disney musical film.', 'Collect musical notes across dreamlike worlds to restore the magic.', 'A visually artistic and music-focused platformer.', 'Fantasia features beautiful 16-bit animation and classic melodies. Guide Apprentice Mickey through surreal environments in this unique Disney Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantasia-world-rev-a', 'Genesis', 'Fantasia (World) (Rev A)', '1991', 'Platformer', 'Sega', '1', 'Platformer', 'Side-scrolling platformer based on the Disney musical film.', 'Collect musical notes across dreamlike worlds to restore the magic.', 'An updated revision (Rev A) of the Fantasia platformer.', 'Fantasia features beautiful 16-bit animation and classic melodies. Guide Apprentice Mickey through surreal environments in this unique Disney Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantastic-dizzy-usa-europe-enfrdeesit', 'Genesis', 'Fantastic Dizzy (USA, Europe) (En,Fr,De,Es,It)', '1993', 'Platformer', 'Traveller''s Tales', '1', 'Platformer', 'Isometric adventure game with puzzle-solving and exploration.', 'Journey through a huge world to collect stars and save the village.', 'A massive and colorful adventure by Codemasters.', 'Fantastic Dizzy brings the iconic egg-hero to the Genesis. Explore vibrant 16-bit locations and solve inventory puzzles in this expansive Sega adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fastest-1-japan', 'Genesis', 'Fastest 1 (Japan)', '1991', 'Shooter', 'NCS', '1', 'Shooter', 'High-speed Formula 1 racing with a focus on arcade play.', 'Outmaneuver opponents and take the checkered flag.', 'A fast-paced Japanese racing title from Human Entertainment.', 'Fastest 1 offers high-octane 16-bit racing action. Experience smooth scrolling and intense competition in this polished Mega Drive racing game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatal-fury-europe', 'Genesis', 'Fatal Fury (Europe)', '1992', 'Fighting', 'SNK', '2', 'Fighting', 'One-on-one fighting game with a unique "plane-switching" mechanic.', 'Defeat Geese Howard''s fighters in the King of Fighters tournament.', 'The legendary SNK fighter ported to the Genesis.', 'Fatal Fury brings arcade-style brawling home. Master special moves and switch between foreground and background in this iconic 16-bit fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatal-fury-usa', 'Genesis', 'Fatal Fury (USA)', '1992', 'Fighting', 'SNK', '2', 'Fighting', 'One-on-one fighting game with a unique "plane-switching" mechanic.', 'Defeat Geese Howard''s fighters in the King of Fighters tournament.', 'The North American release of the SNK hit.', 'Fatal Fury brings arcade-style brawling home. Master special moves and switch between foreground and background in this iconic 16-bit fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatal-fury-2-usa', 'Genesis', 'Fatal Fury 2 (USA)', '1994', 'Fighting', 'SNK', '2', 'Fighting', 'One-on-one fighting game with expanded roster and special moves.', 'Win the global tournament to prove you are the strongest fighter.', 'The high-quality 16-bit sequel to the original Fatal Fury.', 'Fatal Fury 2 features more characters and refined "plane-switching" combat. Experience some of the best 16-bit fighting action available on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatal-fury-one-v15-brazil-unl', 'Genesis', 'Fatal Fury One (v.1.5) (Brazil) (Unl)', '1992', 'Fighting', 'SNK', '2', 'Fighting', 'One-on-one fighting game modification with updated balancing.', 'Master the Lee and Bogard styles to win the street tournament.', 'An unlicensed Brazilian hack of the Fatal Fury engine.', 'Fatal Fury One (v.1.5) offers a modified take on the classic fighter. Experience custom 16-bit balance and character tweaks in this rare South American mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatal-fury-rheo-bout-v1-brazil-unl', 'Genesis', 'Fatal Fury Rheo Bout (v.1) (Brazil) (Unl)', '1992', 'Fighting', 'SNK', '2', 'Fighting', 'One-on-one fighting game modification with custom characters.', 'Fight through a unique roster of warriors to become the champ.', 'An unlicensed Brazilian fighting game built on the Fatal Fury engine.', 'Fatal Fury Rheo Bout provides a unique "bootleg" experience for Sega fans. Discover custom moves and sprites in this rare 16-bit fighting modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatal-labyrinth-usa-europe', 'Genesis', 'Fatal Labyrinth (USA, Europe)', '1991', 'RPG', 'Sega', '1', 'RPG', 'Top-down turn-based dungeon crawler with roguelike elements.', 'Navigate a randomly generated tower to recover the Holy Goblet.', 'A classic and addictive 16-bit dungeon crawler.', 'Fatal Labyrinth offers a unique roguelike experience on the Genesis. Manage your hunger and equipment as you climb the dangerous 16-bit tower.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatal-rewind-usa-europe', 'Genesis', 'Fatal Rewind (USA, Europe)', '1991', 'Action', 'Delphine Software', '1', 'Action', 'Top-down arena shooter with puzzle and rescue elements.', 'Guide your vehicle to collect survivors and reach the exit.', 'A port of the Amiga cult classic (Killing Game Show).', 'Fatal Rewind is a high-speed test of reflexes. Navigate deadly 16-bit traps and blast enemies in this intense and unique Sega action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatman-japan', 'Genesis', 'Fatman (Japan)', '1990', 'Action', 'Irem', '1', 'Action', 'One-on-one fighting game with a focus on heavy combatants.', 'Defeat a roster of massive fighters to win the tournament.', 'A quirky Japanese brawler with unique characters.', 'Fatman (Slaughter Sport) offers a gritty and strange 16-bit fighting experience. Master the unusual controls and defeat bizarre opponents on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('felix-the-cat-unl', 'Genesis', 'Felix the Cat (Unl)', '1992', 'Platformer', 'Shima Shima', '1', 'Platformer', 'Side-scrolling platformer featuring the classic cartoon cat.', 'Rescue your girlfriend Kitty from the Professor''s latest scheme.', 'An unlicensed 16-bit port of the famous platformer.', 'Felix the Cat comes to the Genesis in this rare unlicensed title. Experience the magic-bag-driven 16-bit platforming of the classic cartoon icon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fengshen-yingjie-zhuan-china-unl', 'Genesis', 'Fengshen Yingjie Zhuan (China) (Unl)', '1994', 'RPG', 'Unlicensed', '1', 'RPG', 'Turn-based strategy RPG based on Chinese mythology.', 'Lead your army to victory in the Investiture of the Gods.', 'A deep and visually impressive unlicensed Chinese RPG.', 'Fengshen Yingjie Zhuan offers a massive 16-bit tactical experience. Master mythical spells and lead legendary warriors in this high-quality Mega Drive RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ferias-frustradas-do-pica-pau-brazil', 'Genesis', 'Ferias Frustradas do Pica-Pau (Brazil)', '1995', 'Platformer', 'Tectoy', '1', 'Platformer', 'Side-scrolling platformer starring Woody Woodpecker.', 'Rescue your friends during a disastrous vacation trip.', 'A colorful Brazilian exclusive based on the cartoon.', 'Ferias Frustradas do Pica-Pau brings Woody''s humor to the Genesis. Navigate vibrant 16-bit levels and use wacky gadgets in this rare South American title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ferrari-grand-prix-challenge-usa', 'Genesis', 'Ferrari Grand Prix Challenge (USA)', '1992', 'Racing', 'Genki', '2', 'Racing', 'High-speed Formula 1 racing with a focus on Ferrari cars.', 'Lead the Ferrari team to victory across 16 international tracks.', 'A realistic racing simulation endorsed by Ferrari.', 'Ferrari Grand Prix Challenge offers professional 16-bit racing. Master the Ferrari handling and outpace the field in this detailed Sega racing sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ferrari-grand-prix-challenge-usa-beta', 'Genesis', 'Ferrari Grand Prix Challenge (USA) (Beta)', '1992', 'Racing', 'Genki', '2', 'Racing', 'High-speed Formula 1 racing with a focus on Ferrari cars.', 'Lead the Ferrari team to victory across 16 international tracks.', 'A beta development build of the Ferrari racing title.', 'Peek at the engine tuning of the Ferrari Grand Prix Challenge Beta. A fascinating look at the development of high-speed 16-bit racing for the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fever-pitch-soccer-europe-enfrdeesit', 'Genesis', 'Fever Pitch Soccer (Europe) (En,Fr,De,Es,It)', '1995', 'Sports', 'U.S. Gold', '2', 'Sports', 'Arcade-style soccer with "super" moves and power-ups.', 'Win the international tournament by any means necessary.', 'A high-energy and funny 16-bit soccer game.', 'Fever Pitch Soccer (Mario Lemieux Hockey style) brings arcade chaos to the pitch. Use dirty tactics and special shots in this fast-paced Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fido-dido-usa-proto', 'Genesis', 'Fido Dido (USA) (Proto)', '1992', 'Platformer', 'Sega', '1', 'Platformer', 'Side-scrolling platformer starring the 7-Up mascot''s counterpart.', 'Navigate through your own sketchbook and avoid hazards.', 'An unreleased prototype featuring the cool Fido Dido.', 'Fido Dido is a rare piece of 16-bit history. Experience the unique art style and smooth platforming of this unreleased Sega Genesis cartoon tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-98---road-to-world-cup-europe-enfresitsv', 'Genesis', 'FIFA 98 - Road to World Cup (Europe) (En,Fr,Es,It,Sv)', '1997', 'Sports', 'Electronic Arts', '4', 'Sports', 'Isometric soccer simulation with updated 1998 squads.', 'Qualify for and win the World Cup in France.', 'The final FIFA entry for the 16-bit Sega era.', 'FIFA 98: Road to World Cup brings the most complete rosters and refined gameplay to the Genesis. Experience the road to glory in this swan song for 16-bit sports.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-international-soccer-usa-europe-enfrdees', 'Genesis', 'FIFA International Soccer (USA, Europe) (En,Fr,De,Es)', '1993', 'Sports', 'Electronic Arts', '4', 'Sports', 'Isometric soccer simulation with an arcade feel.', 'Win the international tournament to become world champions.', 'The legendary game that launched the FIFA franchise.', 'FIFA International Soccer revolutionized sports gaming on the Genesis. Master the isometric view and crowd-pleasing goals in this quintessential 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-soccer-95-usa-europe-enfrdees', 'Genesis', 'FIFA Soccer 95 (USA, Europe) (En,Fr,De,Es)', '1994', 'Sports', 'Electronic Arts', '4', 'Sports', 'Isometric soccer simulation with added club teams.', 'Win various league titles and international cups.', 'The first sequel in the FIFA series, exclusive to Genesis.', 'FIFA Soccer 95 introduced club teams and smoother passing. Experience the evolution of 16-bit football with faster gameplay and deeper management options.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-soccer-96-usa-europe-enfrdeesitsv', 'Genesis', 'FIFA Soccer 96 (USA, Europe) (En,Fr,De,Es,It,Sv)', '1995', 'Sports', 'Electronic Arts', '4', 'Sports', 'Isometric soccer simulation with real player names.', 'Lead your team to victory in fully licensed leagues.', 'The first FIFA title to feature real professional players.', 'FIFA Soccer 96 brings authenticity to the pitch with real-life rosters. Enjoy the peak of 16-bit soccer simulation with refined AI and professional tactics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-soccer-97-usa-europe-enfrdeesitsv', 'Genesis', 'FIFA Soccer 97 (USA, Europe) (En,Fr,De,Es,It,Sv)', '1996', 'Sports', 'Electronic Arts', '4', 'Sports', 'Isometric soccer simulation with motion-captured animation.', 'Master the field and win the championship with updated stats.', 'The 1997 edition featuring improved player movement.', 'FIFA Soccer 97 offers the most fluid animations of the 16-bit era. Experience high-stakes football with deep season modes and authentic stadium atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighting-masters-japan', 'Genesis', 'Fighting Masters (Japan)', '1992', 'Fighting', 'Treco', '2', 'Fighting', 'One-on-one fighting game with giant, unique characters.', 'Defeat a series of monstrous warriors to save the galaxy.', 'A quirky and large-scale 16-bit fighting game.', 'Fighting Masters features massive sprites and unconventional combat. Choose your alien warrior and battle for supremacy in this colorful and strange Sega brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighting-masters-usa', 'Genesis', 'Fighting Masters (USA)', '1992', 'Fighting', 'Treco', '2', 'Fighting', 'One-on-one fighting game with giant, unique characters.', 'Defeat a series of monstrous warriors to save the galaxy.', 'The North American release of the giant-warrior fighter.', 'Fighting Masters features massive sprites and unconventional combat. Choose your alien warrior and battle for supremacy in this colorful and strange Sega brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-blow-japan', 'Genesis', 'Final Blow (Japan)', '1990', 'Sports', 'Taito', '2', 'Sports', 'One-on-one boxing simulation with a side-view perspective.', 'Knock out your opponents to climb the professional ranks.', 'A port of the intense Taito arcade boxing game.', 'Final Blow (James ''Buster'' Douglas Knockout Boxing) offers heavy-hitting 16-bit action. Master your timing and deliver the finishing punch in this gritty sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-mustang-japan', 'Genesis', 'Fire Mustang (Japan)', '1990', 'Shooter', 'Taito', '2', 'Shooter', 'Horizontal-scrolling shoot ''em up set in World War II.', 'Pilot a Mustang fighter to destroy enemy air and ground forces.', 'A high-speed aerial combat shmup by Taito.', 'Fire Mustang brings explosive WWII action to the Mega Drive. Navigate through intense bullet patterns and take down massive bosses in this classic 16-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-shark-europe', 'Genesis', 'Fire Shark (Europe)', '1989', 'Shooter', 'Toaplan', '2', 'Shooter', 'Vertical-scrolling shoot ''em up with a focus on fire weapons.', 'Fly the Fire Shark biplane to defeat a mysterious super-army.', 'A legendary and highly-rated arcade shmup port.', 'Fire Shark (Same! Same! Same!) is a masterpiece of the genre. Master the wide-range fire beam and survive relentless enemy waves in this premier 16-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-shark-usa', 'Genesis', 'Fire Shark (USA)', '1989', 'Shooter', 'Toaplan', '2', 'Shooter', 'Vertical-scrolling shoot ''em up with a focus on fire weapons.', 'Fly the Fire Shark biplane to defeat a mysterious super-army.', 'The North American release of the iconic Fire Shark.', 'Fire Shark (Same! Same! Same!) is a masterpiece of the genre. Master the wide-range fire beam and survive relentless enemy waves in this premier 16-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fix-it-felix-jr', 'Genesis', 'Fix it Felix Jr.', '2014', 'Platformer', 'Disney Interactive', '1', 'Platformer', 'Side-scrolling platformer with block-repair mechanics.', 'Repair the building''s windows while avoiding falling debris.', 'A modern "demake" based on the Wreck-It Ralph movie.', 'Fix it Felix Jr. brings the movie''s fictional arcade classic to life on real 16-bit hardware. Experience charming retro gameplay and perfect Sega-style aesthetics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flames-in-sonic-&-knuckles', 'Genesis', 'Flames in Sonic & Knuckles', '1994', 'Modification', 'Fan Made', '1', 'Modification', 'High-speed platforming with the ability to play as "Flames."', 'Complete the game with a custom-skinned fiery protagonist.', 'A visual character modification for Sonic & Knuckles.', 'Flames in Sonic & Knuckles adds a burning aesthetic to the ultimate Sonic adventure. Experience the same tight 16-bit platforming with a scorching new look.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flames-in-sonic-1', 'Genesis', 'Flames in Sonic 1', '1994', 'Modification', 'Fan Made', '1', 'Modification', 'High-speed platforming with the ability to play as "Flames."', 'Complete the game with a custom-skinned fiery protagonist.', 'A visual character modification for the first Sonic game.', 'Flames in Sonic 1 gives the blue blur a fiery makeover. Experience the 16-bit origin story with updated sprites and a unique, glowing visual style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flames-in-sonic-2', 'Genesis', 'Flames in Sonic 2', '1994', 'Modification', 'Fan Made', '1', 'Modification', 'High-speed platforming with the ability to play as "Flames."', 'Complete the game with a custom-skinned fiery protagonist.', 'A visual character modification for the iconic Sonic 2.', 'Flames in Sonic 2 brings a heat-wave to West Side Island. Enjoy the high-speed loops and zones with this custom-colored 16-bit character mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flames-in-sonic-3', 'Genesis', 'Flames in Sonic 3', '1994', 'Modification', 'Fan Made', '1', 'Modification', 'High-speed platforming with the ability to play as "Flames."', 'Complete the game with a custom-skinned fiery protagonist.', 'A visual character modification for Sonic the Hedgehog 3.', 'Flames in Sonic 3 adds a fresh visual spark to Angel Island. Navigate the lush 16-bit environments with this unique, fan-created character variant.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flashback---the-quest-for-identity-usa', 'Genesis', 'Flashback - The Quest for Identity (USA)', '1993', 'Action', 'Delphine Software', '1', 'Cinematic Platformer', 'Cinematic action-adventure with rotoscoped animation.', 'Recover your lost memories and stop an alien conspiracy.', 'A groundbreaking technical marvel for the Genesis.', 'Flashback: The Quest for Identity features incredible animation and a deep sci-fi plot. Master the gunplay and environmental puzzles in this 16-bit cinematic masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flashback---the-quest-for-identity-usa-alt', 'Genesis', 'Flashback - The Quest for Identity (USA) (Alt)', '1993', 'Action', 'Delphine Software', '1', 'Cinematic Platformer', 'Cinematic action-adventure with rotoscoped animation.', 'Recover your lost memories and stop an alien conspiracy.', 'An alternate version of the cinematic platformer.', 'Flashback: The Quest for Identity features incredible animation and a deep sci-fi plot. Master the gunplay and environmental puzzles in this 16-bit cinematic masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flashback-europe', 'Genesis', 'Flashback (Europe)', '1992', 'Action', 'Delphine Software', '1', 'Cinematic Platformer', 'Cinematic action-adventure with rotoscoped animation.', 'Recover your lost memories and stop an alien conspiracy.', 'The European release of the cinematic classic.', 'Flashback: The Quest for Identity features incredible animation and a deep sci-fi plot. Master the gunplay and environmental puzzles in this 16-bit cinematic masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flashback-japan', 'Genesis', 'Flashback (Japan)', '1992', 'Action', 'Delphine Software', '1', 'Cinematic Platformer', 'Cinematic action-adventure with rotoscoped animation.', 'Recover your lost memories and stop an alien conspiracy.', 'The Japanese Mega Drive version of Flashback.', 'Flashback: The Quest for Identity features incredible animation and a deep sci-fi plot. Master the gunplay and environmental puzzles in this 16-bit cinematic masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flicky-usa-europe', 'Genesis', 'Flicky (USA, Europe)', '1991', 'Platformer', 'Sega', '2', 'Platformer', 'Single-screen arcade platformer with physics-based escorting.', 'Lead all the chirping chicks back to the exit while avoiding cats.', 'A charming and addictive port of the Sega arcade hit.', 'Flicky is a 16-bit classic of timing and precision. Save your feathered friends and outsmart the hungry cats in this delightfully simple and fun Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flicky-turncoat-dx', 'Genesis', 'Flicky Turncoat DX', '2020', 'Platformer', 'Fan Made', '1', 'Platformer', 'Enhanced single-screen arcade platformer with new features.', 'Lead the chicks to safety with improved controls and mechanics.', 'A modernized "DX" version of the classic Flicky.', 'Flicky Turncoat DX offers refined gameplay and new challenges for fans of the original. Experience the ultimate 16-bit version of this arcade rescue mission.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flink-europe', 'Genesis', 'Flink (Europe)', '1994', 'Platformer', 'Psygnosis', '1', 'Platformer', 'Side-scrolling action-RPG with a focus on alchemy and magic.', 'Use magical ingredients to cast spells and save your world.', 'A visually stunning platformer with RPG elements.', 'Flink features some of the most detailed 2D art on the system. Master the alchemy system and explore a whimsical 16-bit world in this high-quality Sega adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flintstone-japan', 'Genesis', 'Flintstone (Japan)', '1994', 'Platformer', 'Taito', '1', 'Platformer', 'Side-scrolling platformer based on the classic cartoon.', 'Rescue the Flintstone family from various prehistoric perils.', 'A vibrant and humorous Bedrock adventure.', 'The Flintstones brings the iconic stone-age family to the Genesis. Experience colorful 16-bit levels and classic cartoon humor in this fun Sega platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flintstones-the-europe', 'Genesis', 'Flintstones, The (Europe)', '1994', 'Platformer', 'Taito', '1', 'Platformer', 'Side-scrolling platformer based on the classic cartoon.', 'Rescue the Flintstone family from various prehistoric perils.', 'The European release of the Flintstones adventure.', 'The Flintstones brings the iconic stone-age family to the Genesis. Experience colorful 16-bit levels and classic cartoon humor in this fun Sega platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flintstones-the-usa', 'Genesis', 'Flintstones, The (USA)', '1994', 'Platformer', 'Taito', '1', 'Platformer', 'Side-scrolling platformer based on the classic cartoon.', 'Rescue the Flintstone family from various prehistoric perils.', 'The North American release of the Flintstones adventure.', 'The Flintstones brings the iconic stone-age family to the Genesis. Experience colorful 16-bit levels and classic cartoon humor in this fun Sega platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fly-with-tails-in-sonic-the-hedgehog-2', 'Genesis', 'Fly with Tails in Sonic the Hedgehog 2', '1992', 'Modification', 'Fan Made', '1', 'Modification', 'High-speed platforming with independent flight control.', 'Navigate Sonic 2 stages with Tails'' flight ability unlocked.', 'A mechanical mod for Sonic 2 focusing on Tails.', 'Fly with Tails in Sonic the Hedgehog 2 changes the platforming dynamic. Reach new heights and discover secrets in this 16-bit classic using Tails'' unique flight.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('foreman-for-real-world', 'Genesis', 'Foreman for Real (World)', '1995', 'Sports', 'Acclaim', '2', 'Sports', 'One-on-one boxing simulation with a "behind-the-back" view.', 'Win the world championship by out-punching the competition.', 'A realistic boxing game featuring George Foreman.', 'Foreman for Real offers a close-up perspective of the ring. Master the 16-bit dodge and counter-punch in this detailed and gritty sports simulation for Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('forgotten-worlds-world', 'Genesis', 'Forgotten Worlds (World)', '1988', 'Shooter', 'Capcom', '2', 'Arcade Shooter', 'Side-scrolling shoot ''em up with 360-degree firing.', 'Defeat the God of War and reclaim the planet for humanity.', 'A legendary Capcom arcade port with shop mechanics.', 'Forgotten Worlds features unique controls and a deep upgrade system. Fly through impressive 16-bit levels and battle massive bosses in this iconic Sega shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('forgotten-worlds-world-v11', 'Genesis', 'Forgotten Worlds (World) (v1.1)', '1988', 'Shooter', 'Capcom', '2', 'Arcade Shooter', 'Side-scrolling shoot ''em up with 360-degree firing.', 'Defeat the God of War and reclaim the planet for humanity.', 'An updated revision (v1.1) of the Capcom classic.', 'Forgotten Worlds features unique controls and a deep upgrade system. Fly through impressive 16-bit levels and battle massive bosses in this iconic Sega shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('formula-one-usa', 'Genesis', 'Formula One (USA)', '1993', 'Racing', 'Domark', '2', 'Racing', 'High-speed Formula 1 racing with a focus on realism.', 'Win the world championship by mastering international tracks.', 'The North American release of the Domark racing sim.', 'Formula One brings professional grand prix racing to your Genesis. Master pit strategy and tight cornering in this authentic and challenging 16-bit simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frank-thomas-big-hurt-baseball-usa-europe', 'Genesis', 'Frank Thomas Big Hurt Baseball (USA, Europe)', '1995', 'Sports', 'Acclaim Entertainment', '2', 'Sports', 'Professional baseball simulation with realistic player motion.', 'Lead your team to victory through a full MLB-style season.', 'A detailed baseball sim featuring "The Big Hurt."', 'Frank Thomas Big Hurt Baseball offers smooth 16-bit animations and deep stats. Master the plate and the mound in this definitive Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frogger-usa', 'Genesis', 'Frogger (USA)', '1998', 'Action', 'Konami', '2', 'Arcade Action', 'Classic arcade action with a modern visual update.', 'Guide frogs across a busy road and river to reach safety.', 'A faithful 16-bit remake of the arcade legend.', 'Frogger on the Genesis brings the timeless "hop-and-dodge" gameplay to 16-bit. Experience updated graphics while maintaining the classic arcade challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('from-tv-animation-slam-dunk---kyougou-makkou-taiketsu!-japan', 'Genesis', 'From TV Animation Slam Dunk - Kyougou Makkou Taiketsu! (Japan)', '1994', 'Sports', 'Bandai', '2', 'Sports', 'Side-scrolling basketball with anime-style special moves.', 'Win the high school championship with the Shohoku team.', 'A high-energy sports game based on the hit anime.', 'From TV Animation Slam Dunk features cinematic dunks and dramatic 16-bit action. Experience the passion of the manga on your Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frozen-tails-in-sonic-the-hedgehog', 'Genesis', 'Frozen Tails in Sonic The Hedgehog', '1991', 'Modification', 'Fan Made', '1', 'Modification', 'High-speed platforming with a custom "Frozen" aesthetic.', 'Navigate classic levels as a winter-themed Tails.', 'A visual character modification for the Sonic engine.', 'Frozen Tails in Sonic The Hedgehog adds a chilly twist to the original game. Play as a re-colored, icy version of the famous fox in this 16-bit fan mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fun-n-games-europe', 'Genesis', 'Fun ''N'' Games (Europe)', '1993', 'Educational', 'Leland Interactive Media', '2', 'Educational', 'Multi-activity suite featuring drawing, music, and mini-games.', 'Express your creativity or compete in various simple games.', 'A creative "edutainment" suite for the Genesis.', 'Fun ''N'' Games turns your console into a creative studio. Compose music, paint digital masterpieces, and enjoy quirky 16-bit mini-games in this varied collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fun-n-games-usa', 'Genesis', 'Fun ''N'' Games (USA)', '1993', 'Educational', 'Leland Interactive Media', '2', 'Educational', 'Multi-activity suite featuring drawing, music, and mini-games.', 'Express your creativity or compete in various simple games.', 'The North American release of the creative suite.', 'Fun ''N'' Games turns your console into a creative studio. Compose music, paint digital masterpieces, and enjoy quirky 16-bit mini-games in this varied collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fun-car-rally-usa-proto', 'Genesis', 'Fun Car Rally (USA) (Proto)', '1994', 'Racing', 'Sega', '2', 'Racing', 'Isometric racing with an emphasis on drifting and speed.', 'Outrun rivals on a variety of creative tracks.', 'An unreleased prototype of a high-energy racer.', 'Fun Car Rally is a rare glimpse into a "lost" Sega title. Experience fast-paced isometric racing and tight 16-bit controls in this unreleased prototype.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fushigi-no-umi-no-nadia-japan', 'Genesis', 'Fushigi no Umi no Nadia (Japan)', '1991', 'Adventure', 'Gainax', '1', 'Adventure', 'Tactical adventure game based on the Gainax anime.', 'Follow Nadia and Jean to uncover the secrets of Blue Water.', 'A story-driven Japanese adventure (Secret of Blue Water).', 'Fushigi no Umi no Nadia brings the classic anime to life. Experience deep 16-bit storytelling and beautiful character art on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fz-senki-axis-~-final-zone-japan-usa', 'Genesis', 'FZ Senki Axis ~ Final Zone (Japan, USA)', '1990', 'Shooter', 'Wolf Team', '2', 'Shooter', 'Isometric mech combat with a focus on directional shooting.', 'Pilot your mech through enemy lines to stop a global threat.', 'An intense isometric shooter (Final Zone).', 'FZ Senki Axis delivers explosive mech action. Master the unique perspective and heavy weaponry in this gritty and challenging 16-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('g-loc-air-battle-world', 'Genesis', 'G-LOC Air Battle (World)', '1990', 'Shooter', 'Sega', '2', 'Shooter', 'First-person aerial combat simulation with scaling graphics.', 'Shoot down enemy jets and complete missions within time.', 'A fast-paced arcade port of the flight simulator.', 'G-LOC Air Battle brings "Into-the-screen" action to the Genesis. Experience the thrill of 16-bit dogfighting with impressive sprite-scaling technology.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('g-loc-air-battle-world-beta', 'Genesis', 'G-LOC Air Battle (World) (Beta)', '1990', 'Shooter', 'Sega', '2', 'Shooter', 'First-person aerial combat simulation with scaling graphics.', 'Shoot down enemy jets and complete missions within time.', 'A beta development build of G-LOC.', 'Peek at the development of 16-bit flight physics in the G-LOC Beta. Discover how Sega optimized high-speed dogfighting for the Genesis hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gadget-twins-usa', 'Genesis', 'Gadget Twins (USA)', '1993', 'Action', 'Imagitec Design', '2', 'Action', 'Side-scrolling shoot ''em up featuring two mechanical twins.', 'Blast through waves of enemies in a whimsical toy-like world.', 'A colorful and family-friendly horizontal shooter.', 'Gadget Twins features vibrant 16-bit graphics and unique "hook" mechanics. Navigate creative levels in this charming and accessible Sega shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gaiares-japan-usa', 'Genesis', 'Gaiares (Japan, USA)', '1990', 'Shooter', 'Telenet Japan', '2', 'Shooter', 'Horizontal-scrolling shoot ''em up with a weapon-stealing mechanic.', 'Use the TOZ system to steal enemy weapons and save Earth.', 'A legendary and difficult high-tier 16-bit shmup.', 'Gaiares is a masterpiece of the genre. Master the unique weapon-capture system and enjoy some of the most impressive 16-bit boss fights on the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gain-ground-world', 'Genesis', 'Gain Ground (World)', '1991', 'Action', 'Sega', '2', 'Action', 'Tactical overhead action with multiple playable characters.', 'Rescue allies and reach the exit of each complex stage.', 'A brilliant arcade-to-home port of the strategy-action hit.', 'Gain Ground is a 16-bit tactical essential. Use different character classes to outsmart the enemy in this deep and rewarding Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gain-ground-world-alt', 'Genesis', 'Gain Ground (World) (Alt)', '1991', 'Action', 'Sega', '2', 'Action', 'Tactical overhead action with multiple playable characters.', 'Rescue allies and reach the exit of each complex stage.', 'An alternate version of the tactical action port.', 'Gain Ground is a 16-bit tactical essential. Use different character classes to outsmart the enemy in this deep and rewarding Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galaxy-force-ii-world', 'Genesis', 'Galaxy Force II (World)', '1991', 'Shooter', 'Sega', '1', 'Arcade Shooter', 'Into-the-screen 3D rail shooter with sprite-scaling tech.', 'Protect the galaxy by destroying the Halcyon Empire''s forces.', 'A technical showcase for the Mega Drive hardware.', 'Galaxy Force II pushes the 16-bit limits with impressive scaling and rotation. Experience the thrill of the arcade original on your home console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galaxy-force-ii-world-rev-b', 'Genesis', 'Galaxy Force II (World) (Rev B)', '1991', 'Shooter', 'Sega', '1', 'Arcade Shooter', 'Into-the-screen 3D rail shooter with sprite-scaling tech.', 'Protect the galaxy by destroying the Halcyon Empire''s forces.', 'An updated revision (Rev B) of the scaling shooter.', 'Galaxy Force II pushes the 16-bit limits with impressive scaling and rotation. Experience the thrill of the arcade original on your home console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gambler-jiko-chuushinha---katayama-masayuki-no-mahjong-doujou-japan', 'Genesis', 'Gambler Jiko Chuushinha - Katayama Masayuki no Mahjong Doujou (Japan)', '1994', 'Board Game', 'Sega', '1', 'Board Game', 'Mahjong simulation featuring characters from the manga.', 'Master the tiles and defeat opponents in various tournaments.', 'A humorous and stylish Japanese Mahjong game.', 'Gambler Jiko Chuushinha brings the quirky manga world to the Mega Drive. Experience authentic Mahjong gameplay with 16-bit personality.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('game-no-kandume-otokuyou-japan', 'Genesis', 'Game no Kandume Otokuyou (Japan)', '1995', 'Compilation', 'Sega', '1', 'Compilation', 'A massive compilation of classic Sega arcade and home hits.', 'Enjoy a variety of retro games in one convenient package.', 'A "Can of Games" collection exclusive to Japan.', 'Game no Kandume Otokuyou is a treasure trove for Sega fans. Play various 8-bit and 16-bit classics in this rare and comprehensive Japanese collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garfield---caught-in-the-act-usa-europe', 'Genesis', 'Garfield - Caught in the Act (USA, Europe)', '1995', 'Platformer', 'Disney Interactive', '1', 'Platformer', 'Side-scrolling platformer with a "movie-hopping" theme.', 'Rescue your friends and escape the digital world of television.', 'A visually impressive platformer starring the orange cat.', 'Garfield: Caught in the Act features incredible hand-drawn animation. Explore diverse movie-themed 16-bit worlds in this high-quality Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gargoyles-usa', 'Genesis', 'Gargoyles (USA)', '1995', 'Action', 'Disney Interactive', '1', 'Action', 'Side-scrolling action platformer with incredible animation.', 'Protect the city and defeat the Steel Clan and other threats.', 'A dark, atmospheric masterpiece based on the Disney show.', 'Gargoyles is a technical marvel on the Genesis. Use claws and wings to navigate gritty 16-bit environments in this challenging and beautiful action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garou-densetsu---shukumei-no-tatakai-japan', 'Genesis', 'Garou Densetsu - Shukumei no Tatakai (Japan)', '1991', 'Fighting', 'SNK', '2', 'Fighting', 'One-on-one fighting game with a unique plane-switching mechanic.', 'Defeat the fighters of South Town to stop Geese Howard.', 'The Japanese Mega Drive version of Fatal Fury.', 'Garou Densetsu brings the SNK legend to the Mega Drive. Master the "Hungry Wolf" style in this quintessential 16-bit fighting port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garou-densetsu-2---aratanaru-tatakai-japan', 'Genesis', 'Garou Densetsu 2 - Aratanaru Tatakai (Japan)', '1992', 'Fighting', 'SNK', '2', 'Fighting', 'One-on-one fighting game with an expanded roster of warriors.', 'Travel the world to prove you are the strongest fighter.', 'The Japanese Mega Drive version of Fatal Fury 2.', 'Garou Densetsu 2 offers refined 16-bit combat and iconic characters. Experience the height of SNK brawling on the Sega hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gauntlet-japan-enja', 'Genesis', 'Gauntlet (Japan) (En,Ja)', '1991', 'Action', 'Tengen', '4', 'Arcade Action', 'Overhead dungeon-crawling action for up to four players.', 'Navigate deadly mazes, collect treasure, and survive the hordes.', 'The Japanese release of the legendary fantasy crawler.', 'Gauntlet on the Mega Drive delivers pure co-op mayhem. Battle through endless 16-bit dungeons and keep your health from hitting zero.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gauntlet-iv-usa-europe-enja-august-1993', 'Genesis', 'Gauntlet IV (USA, Europe) (En,Ja) (August 1993)', '1993', 'Action', 'Tengen', '4', 'Arcade Action', 'Overhead dungeon-crawling action with multiple game modes.', 'Conquer the towers and defeat the ancient evil within.', 'The definitive console version of the Gauntlet series.', 'Gauntlet IV is a 16-bit masterpiece. Featuring the original arcade mode plus a massive new RPG Quest mode, it''s the ultimate fantasy action game for Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gauntlet-iv-usa-europe-enja-september-1993', 'Genesis', 'Gauntlet IV (USA, Europe) (En,Ja) (September 1993)', '1993', 'Action', 'Tengen', '4', 'Arcade Action', 'Overhead dungeon-crawling action with multiple game modes.', 'Conquer the towers and defeat the ancient evil within.', 'The September 1993 revision of the fantasy classic.', 'Gauntlet IV is a 16-bit masterpiece. Featuring the original arcade mode plus a massive new RPG Quest mode, it''s the ultimate fantasy action game for Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gemfire-usa', 'Genesis', 'Gemfire (USA)', '1991', 'Strategy', 'Koei', '1', 'Strategy', 'Tactical grid-based strategy with a focus on magical gems.', 'Reunite the 24 gems to bring peace to the land of Ishmeria.', 'A deep and accessible strategy RPG by Koei.', 'Gemfire blends 16-bit resource management with tactical combat. Lead mythical creatures and knights to victory in this engaging fantasy epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('general-chaos-usa-europe', 'Genesis', 'General Chaos (USA, Europe)', '1994', 'Action', 'Game Refuge', '4', 'Action', 'Squad-based tactical combat with a humorous, gritty style.', 'Lead your 5-man squad to eliminate the opposing army.', 'A unique and frantic "point-and-click" action game.', 'General Chaos is a co-op 16-bit riot. Manage your units in real-time battles and use diverse weapons to win the war on your Sega Genesis.');
