INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gynoug-europe', 'Genesis', 'Gynoug (Europe)', '1991', 'Shooter', 'NCS', '1', 'Shoot ''em Up', 'Horizontal-scrolling shoot ''em up with a mythological theme.', 'Pilot a winged warrior to defeat grotesque biological threats.', 'A dark and atmospheric 16-bit shmup (Wings of Wor).', 'Gynoug features incredible art and massive bosses. Use powerful magic and upgrades to survive this gothic 16-bit shooter on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gynoug-japan', 'Genesis', 'Gynoug (Japan)', '1991', 'Shooter', 'NCS', '1', 'Shoot ''em Up', 'Horizontal-scrolling shoot ''em up with a mythological theme.', 'Pilot a winged warrior to defeat grotesque biological threats.', 'The Japanese version of the dark fantasy shooter.', 'Gynoug features incredible art and massive bosses. Use powerful magic and upgrades to survive this gothic 16-bit shooter on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hard-drivin-world', 'Genesis', 'Hard Drivin'' (World)', '1989', 'Racing', 'Atari Games', '1', 'Racing', '3D-style racing simulation with realistic physics and jumps.', 'Complete the course within the time limit without crashing.', 'An early 3D polygonal racing port for the Genesis.', 'Hard Drivin'' brings the realistic arcade experience home. Master the manual transmission and survive the "stunt track" in this unique 16-bit simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hardball-94-usa-europe', 'Genesis', 'HardBall ''94 (USA, Europe)', '1993', 'Sports', 'Accolade', '2', 'Baseball', 'Professional baseball simulation with deep stats and rosters.', 'Win the World Series through a complete 162-game season.', 'A highly detailed baseball sim by Accolade.', 'HardBall ''94 offers realistic 16-bit baseball gameplay. Master the "pitch-tracking" system and lead your team to glory in this deep sports title.');
