INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hardball-iii-usa', 'Genesis', 'HardBall III (USA)', '1992', 'Sports', 'Accolade', '2', 'Baseball', 'Professional baseball simulation with a focus on realism.', 'Win the World Series through a complete 162-game season.', 'The third entry in the acclaimed HardBall series.', 'HardBall III brings professional baseball to your 16-bit console. Experience detailed player stats and smooth fielding in this classic Sega sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hardball!-usa', 'Genesis', 'HardBall! (USA)', '1989', 'Sports', 'Accolade', '2', 'Baseball', 'Professional baseball simulation with a focus on realism.', 'Win the World Series through a complete 162-game season.', 'The original entry that brought the PC hit to Genesis.', 'HardBall! set the standard for 16-bit baseball. Manage your lineup and master the diamond in this foundational Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter-r-unl', 'Genesis', 'Harry Potter (R) (Unl)', '2001', 'Unlicensed', 'Unknown', '1', 'Unlicensed', 'Side-scrolling action adventure based on the wizarding world.', 'Navigate Hogwarts and defeat enemies using magical spells.', 'A rare and obscure unlicensed Harry Potter game.', 'Harry Potter (Unl) is a unique piece of 16-bit history. Experience a custom-built magical adventure on the Genesis hardware in this rare unofficial title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('haunting-starring-polterguy-usa-europe', 'Genesis', 'Haunting Starring Polterguy (USA, Europe)', '1993', 'Action', 'Sega', '1', 'Action Adventure', 'Isometric puzzle-adventure where you play as a ghost.', 'Scare a greedy family out of their mansion using "scare traps."', 'A creative and funny "scare-''em-up" adventure.', 'Haunting Starring Polterguy is a unique 16-bit experience. Possess household objects to terrify your targets in this stylish and original Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('havoc-europe', 'Genesis', 'Havoc (Europe)', '1990', 'Action', 'Probe Software', '1', 'Action', 'Side-scrolling platformer with a fast-paced "hedgehog-style" feel.', 'Rescue your friends and defeat the evil robotic forces.', 'A vibrant and energetic platformer by Data East.', 'Havoc (High Seas Havoc) features beautiful 16-bit art and tight controls. Master the high-speed platforming and boss battles in this underrated Sega gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('head-on-soccer-usa', 'Genesis', 'Head-On Soccer (USA)', '1994', 'Sports', 'U.S. Gold', '2', 'Soccer', 'Isometric soccer simulation with an emphasis on arcade speed.', 'Win the world championship by out-passing and scoring.', 'A fast-paced and fluid 16-bit soccer title.', 'Head-On Soccer offers high-energy football action. Master the "bend" on your shots and dominate the pitch in this colorful and fun Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heavy-nova-usa', 'Genesis', 'Heavy Nova (USA)', '1991', 'Fighting', 'Konami', '2', 'Fighting', 'Hybrid of side-scrolling platformer and one-on-one mech fighter.', 'Pilot a heavy robot through levels to face rival mechs.', 'A unique blend of exploration and robot brawling.', 'Heavy Nova offers a different take on the 16-bit action genre. Upgrade your mech and master technical combat in this sci-fi Genesis title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heavy-unit---mega-drive-special-japan', 'Genesis', 'Heavy Unit - Mega Drive Special (Japan)', '1991', 'Shooter', 'Kaneshiro', '1', 'Shoot ''em Up', 'Horizontal-scrolling shoot ''em up with a transforming ship.', 'Pilot a mech that can change forms to survive alien waves.', 'A classic Taito arcade port with impressive visuals.', 'Heavy Unit: Mega Drive Special features intense 16-bit shooting. Transform between a ship and a powerful robot to crush the alien threat on your console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hellfire-europe', 'Genesis', 'Hellfire (Europe)', '1990', 'Shooter', 'Toaplan', '2', 'Shoot ''em Up', 'Horizontal-scrolling shoot ''em up with four firing directions.', 'Navigate dangerous space corridors and destroy enemy cores.', 'A tactical and challenging shmup by Toaplan.', 'Hellfire is a 16-bit shooter essential. Master the four-way weapon switching system to survive some of the most complex levels on the Sega Genesis.');
