INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hercules-2-unl', 'Genesis', 'Hercules 2 (Unl)', '1999', 'Platformer', 'Unknown', '1', 'Platformer', 'Side-scrolling action platformer based on the mythical hero.', 'Defeat mythological monsters and complete the labors.', 'An unlicensed 16-bit sequel to the Disney-style hero.', 'Hercules 2 brings more 8-bit-to-16-bit style action to your console. Navigate ancient Greece in this rare and unofficial platforming adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('herzog-zwei-japan', 'Genesis', 'Herzog Zwei (Japan)', '1989', 'Strategy', 'Tecno Soft', '2', 'Real-Time Strategy', 'Real-time strategy with a mix of overhead and side-scrolling action.', 'Command your units and capture bases to defeat the enemy.', 'A revolutionary and influential early RTS masterpiece.', 'Herzog Zwei is the father of the MOBA and modern RTS. Manage resources, command troops, and pilot your transforming mech in this 16-bit Sega classic.');
