INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('high-seas-havoc-early-prototype', 'Genesis', 'High Seas Havoc (early prototype)', '1993', 'Platformer', 'Data East', '1', 'Platformer', 'Fast-paced platforming with a nautical theme.', 'Navigate early level designs and test character physics.', 'An early development build of the pirate-themed platformer.', 'This early prototype of High Seas Havoc offers a glimpse into the development of a 16-bit gem. Explore unfinished levels and refined sprite work on the Genesis.');
