INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hit-the-ice-usa', 'Genesis', 'Hit the Ice (USA)', '1990', 'Sports', 'Taito', '2', 'Ice Hockey', 'Arcade-style hockey with 3-on-3 gameplay and "super" shots.', 'Out-score and out-fight the opposing team to win the match.', 'A quirky, combat-heavy 16-bit hockey game.', 'Hit the Ice brings the "Video Hockey League" to your console. Use illegal checks and powerful special shots in this fast-paced and funny 16-bit sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hokuto-no-ken---shin-seikimatsu-kyuuseishu-densetsu-japan', 'Genesis', 'Hokuto no Ken - Shin Seikimatsu Kyuuseishu Densetsu (Japan)', '1992', 'Fighting', 'Sega', '1', 'Fighting', 'Side-scrolling beat ''em up based on the famous manga/anime.', 'Defeat the post-apocalyptic gangs as the successor of Hokuto Shinken.', 'The Japanese version of the cult classic "Last Battle."', 'Hokuto no Ken brings Fist of the North Star to the Mega Drive. Experience the original blood and grit in this challenging 16-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('home-alone-usa', 'Genesis', 'Home Alone (USA)', '1991', 'Platformer', 'Imagineering', '1', 'Platformer', 'Strategy-action with trap-laying and exploration mechanics.', 'Defend the McCallister house from the "Wet Bandits" for 20 minutes.', 'A unique 16-bit adaptation of the holiday movie.', 'Home Alone on the Genesis lets you craft creative traps. Explore the neighborhood and gather parts to stop Harry and Marv in this technical 16-bit strategy-action hybrid.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('home-alone-usa-beta', 'Genesis', 'Home Alone (USA) (Beta)', '1991', 'Platformer', 'Imagineering', '1', 'Platformer', 'Strategy-action with trap-laying and exploration mechanics.', 'Defend the McCallister house from the "Wet Bandits" for 20 minutes.', 'A beta development version of the Home Alone movie game.', 'Explore early trap mechanics in the Home Alone Beta. A rare look at how Sega developed the non-linear gameplay for this holiday 16-bit classic.');
