INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hunter-tails-in-sonic-1', 'Genesis', 'Hunter Tails in Sonic 1', '2020', 'Modification', 'Fan Made', '1', 'Modification', 'High-speed platforming with an aggressive custom protagonist.', 'Hunt down Robotnik''s forces as a specialized version of Tails.', 'A character-swap mod for the original Sonic 1.', 'Hunter Tails in Sonic 1 gives the famous fox a more combat-focused edge. Explore South Island with unique flying and attack patterns in this 16-bit mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hurricanes-europe', 'Genesis', 'Hurricanes (Europe)', '1994', 'Action', 'Electronic Arts', '2', 'Action', 'Side-scrolling platformer featuring characters from the show.', 'Travel the world to recover the stolen Hurricanes equipment.', 'A fast-paced soccer-themed action platformer.', 'Hurricanes brings the animated stars to your Genesis. Navigate global 16-bit stages and use soccer skills to defeat your rivals in this unique tie-in.');
