INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hyper-sonic-in-sonic-1-with-spindash', 'Genesis', 'Hyper Sonic in Sonic 1 (with Spindash)', '2022', 'Modification', 'Fan Made', '1', 'Modification', 'High-speed platforming with the ultimate transformation.', 'Clear Sonic 1 levels using the invincible Hyper Sonic form.', 'A mechanical mod adding Hyper Sonic and Spindash to Sonic 1.', 'Hyper Sonic in Sonic 1 brings the power of the sequels to the original. Blitz through zones with incredible speed and the classic 16-bit spindash.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hyper-sonic-in-sonic-2', 'Genesis', 'Hyper Sonic in Sonic 2', '2022', 'Modification', 'Fan Made', '1', 'Modification', 'High-speed platforming with the ultimate transformation.', 'Clear Sonic 2 levels using the invincible Hyper Sonic form.', 'A mechanical mod adding the Hyper form to Sonic 2.', 'Experience the ultimate power trip with Hyper Sonic in Sonic 2. This 16-bit mod lets you use the screen-clearing jump and top speeds throughout West Side Island.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('i-hog-that-hate-hedge', 'Genesis', 'I Hog That Hate Hedge', '2021', 'Modification', 'Fan Made', '1', 'Modification', 'Abstract high-speed platforming with a humorous twist.', 'Navigate surreal levels in this quirky Sonic modification.', 'A experimental and funny "glitch" style Sonic mod.', 'I Hog That Hate Hedge offers a bizarre and funny take on the 16-bit platformer. Explore weird visuals and modified physics in this unique fan creation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('i-made-you-a-salad', 'Genesis', 'I made you a Salad', '2021', 'Modification', 'Fan Made', '1', 'Modification', 'High-speed platforming with food-themed visuals.', 'Complete the game with custom-skinned, salad-themed levels.', 'A humorous and creative aesthetic mod for the Sonic engine.', 'I Made You a Salad brings a literal food fight to the 16-bit era. Enjoy the classic platforming with a bizarrely creative new visual theme.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('img-international-tour-tennis-usa-europe', 'Genesis', 'IMG International Tour Tennis (USA, Europe)', '1994', 'Sports', 'Magical Company', '2', 'Tennis', 'Realistic tennis simulation with official international licenses.', 'Win the world tour by mastering various court surfaces.', 'A detailed and professional 16-bit tennis sim.', 'IMG International Tour Tennis offers precision controls and deep tournament play. Compete against the pros in this polished and realistic Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('immortal-the-usa-europe', 'Genesis', 'Immortal, The (USA, Europe)', '1992', 'Action', 'Electronic Arts', '1', 'Action Adventure', 'Isometric action-RPG with a focus on dark fantasy and traps.', 'Guide your hero through a deadly labyrinth to find the Fountain of Youth.', 'A gritty and atmospheric 16-bit cult classic.', 'The Immortal is known for its brutal difficulty and cinematic death scenes. Solve lethal puzzles and master tactical combat in this dark Sega adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incredible-crash-dummies-the-usa-europe', 'Genesis', 'Incredible Crash Dummies, The (USA, Europe)', '1994', 'Platformer', 'Gray Matter', '1', 'Platformer', 'Side-scrolling action platformer with physics-based comedy.', 'Test various vehicles and survive dangerous crash-test levels.', 'A colorful and wacky action game based on the toys.', 'The Incredible Crash Dummies features unique 16-bit character physics. Explore creative levels and survive spectacular crashes in this fun and quirky Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incredible-crash-dummies-the-usa-beta', 'Genesis', 'Incredible Crash Dummies, The (USA) (Beta)', '1994', 'Platformer', 'Gray Matter', '1', 'Platformer', 'Side-scrolling action platformer with physics-based comedy.', 'Test various vehicles and survive dangerous crash-test levels.', 'A beta development build of the Crash Dummies game.', 'See the early testing of 16-bit crash physics in the Incredible Crash Dummies Beta. A rare look at the development of this quirky Sega Genesis title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incredible-hulk-the-usa-europe', 'Genesis', 'Incredible Hulk, The (USA, Europe)', '1994', 'Action', 'U.S. Gold', '1', 'Action', 'Side-scrolling beat ''em up and platformer with transformations.', 'Destroy the Leader''s forces and find a cure for your gamma radiation.', 'An intense and detailed 16-bit superhero brawler.', 'The Incredible Hulk features massive sprites and destructive 16-bit action. Bash through walls and transform into different Hulk forms to save the world on Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('indiana-jones-and-the-last-crusade-europe', 'Genesis', 'Indiana Jones and the Last Crusade (Europe)', '1992', 'Action', 'Tiertex', '1', 'Action', 'Side-scrolling action adventure with puzzle and platforming elements.', 'Recover the Holy Grail and survive the Nazi forces.', 'A cinematic 16-bit adaptation of the third Indy film.', 'Indiana Jones and the Last Crusade features challenging levels and movie-accurate scenes. Master the whip and solve 16-bit mysteries on your Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('indiana-jones-and-the-last-crusade-usa', 'Genesis', 'Indiana Jones and the Last Crusade (USA)', '1992', 'Action', 'Tiertex', '1', 'Action', 'Side-scrolling action adventure with puzzle and platforming elements.', 'Recover the Holy Grail and survive the Nazi forces.', 'The North American release of the cinematic Indy adventure.', 'Indiana Jones and the Last Crusade features challenging levels and movie-accurate scenes. Master the whip and solve 16-bit mysteries on your Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('insector-x-japan', 'Genesis', 'Insector X (Japan)', '1990', 'Shooter', 'Irem', '1', 'Shoot ''em Up', 'Horizontal-scrolling shoot ''em up with an insect theme.', 'Pilot a miniaturized warrior to defeat a mechanical insect army.', 'A quirky and colorful 16-bit arcade shooter port.', 'Insector X offers a unique perspective on the shmup genre. Battle through bug-infested 16-bit stages with upgradable weaponry in this classic Sega Mega Drive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('insector-x-usa', 'Genesis', 'Insector X (USA)', '1990', 'Shooter', 'Irem', '1', 'Shoot ''em Up', 'Horizontal-scrolling shoot ''em up with an insect theme.', 'Pilot a miniaturized warrior to defeat a mechanical insect army.', 'The North American release of the insect-themed shooter.', 'Insector X offers a unique perspective on the shmup genre. Battle through bug-infested 16-bit stages with upgradable weaponry in this classic Sega Genesis title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('instruments-of-chaos-starring-young-indiana-jones-usa', 'Genesis', 'Instruments of Chaos Starring Young Indiana Jones (USA)', '1994', 'Action', 'LucasArts', '1', 'Action Adventure', 'Side-scrolling action-adventure with a focus on whip combat.', 'Infiltrate enemy lines and stop global threats during WWI.', 'A challenging action game featuring a young Indy.', 'Instruments of Chaos Starring Young Indiana Jones features fluid 16-bit whip mechanics. Travel across global theaters of war in this detailed and difficult Sega adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('instruments-of-chaos-starring-young-indiana-jones-usa-beta', 'Genesis', 'Instruments of Chaos Starring Young Indiana Jones (USA) (Beta)', '1994', 'Action', 'LucasArts', '1', 'Action Adventure', 'Side-scrolling action-adventure with a focus on whip combat.', 'Infiltrate enemy lines and stop global threats during WWI.', 'A beta development version of the Young Indy game.', 'Explore the early mission layouts of the Instruments of Chaos Beta. A fascinating look at the development of 16-bit stealth and action on the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-rugby-europe', 'Genesis', 'International Rugby (Europe)', '1993', 'Sports', 'Beam Software', '2', 'Sports', 'Rugby simulation with a focus on tactical play and scrums.', 'Lead your national team to victory in the international tour.', 'A realistic and detailed 16-bit rugby simulation.', 'International Rugby brings the intensity of the pitch to your console. Master the 16-bit scrum and line-out in this comprehensive Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-superstar-soccer-deluxe-europe', 'Genesis', 'International Superstar Soccer Deluxe (Europe)', '1997', 'Sports', 'Konami', '4', 'Soccer', 'Side-scrolling soccer with detailed sprites and "super" moves.', 'Win the international cup using advanced dribbling and shots.', 'One of the most acclaimed 16-bit soccer games ever.', 'International Superstar Soccer Deluxe is the pinnacle of 16-bit football. Experience incredible animations and deep tactical options on your Sega Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('iron-man-unl', 'Genesis', 'Iron Man (Unl)', '1995', 'Action', 'Realtime Associates', '1', 'Action', 'Side-scrolling action brawler featuring the Marvel hero.', 'Defeat various supervillains and protect the world.', 'A rare and obscure unlicensed 16-bit Marvel title.', 'Iron Man (Unl) offers a unique "bootleg" take on the armored Avenger. Experience custom 16-bit sprites and combat in this rare unlicensed Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ishido---the-way-of-stones-usa', 'Genesis', 'Ishido - The Way of Stones (USA)', '1990', 'Puzzle', 'Publishing International', '2', 'Board Game', 'Strategy puzzle game based on tile matching and placement.', 'Master the "Way of Stones" by clearing the board via symbols.', 'A meditative and challenging 16-bit logic puzzle.', 'Ishido: The Way of Stones offers a deep test of strategy and foresight. Experience a zen-like puzzle challenge with beautiful 16-bit tile designs on the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('it-came-from-the-desert-usa', 'Genesis', 'It Came from the Desert (USA)', '1990', 'Adventure', 'Cinemaware', '1', 'Adventure', 'Top-down action-adventure and strategy hybrid.', 'Defend a desert town from an invasion of giant mutated ants.', 'A cinematic cult classic based on the PC original.', 'It Came from the Desert features a 1950s sci-fi aesthetic. Manage your time and fight off 16-bit giant insects in this unique and atmospheric Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('itchy-and-scratchy-game-the-usa-proto', 'Genesis', 'Itchy and Scratchy Game, The (USA) (Proto)', '1993', 'Platformer', 'Bits Studios', '1', 'Platformer', 'Side-scrolling brawler featuring the violent cartoon duo.', 'Inflict as much cartoon mayhem as possible to win the stage.', 'An unreleased 16-bit prototype of the Simpsons spin-off.', 'The Itchy and Scratchy Game brings the "show within a show" to life. Experience rare 16-bit cartoon violence in this unreleased Sega Genesis prototype.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('izzys-quest-for-the-olympic-rings-usa-europe', 'Genesis', 'Izzy''s Quest for the Olympic Rings (USA, Europe)', '1992', 'Sports', 'Rare', '2', 'Sports', 'Side-scrolling platformer featuring the 1996 Olympic mascot.', 'Collect the Olympic rings across various surreal dream worlds.', 'A colorful and energetic mascot platformer.', 'Izzy''s Quest for the Olympic Rings features vibrant 16-bit graphics and unique transformations. Explore imaginative levels in this high-energy Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('j-league-champion-soccer-japan', 'Genesis', 'J. League Champion Soccer (Japan)', '1992', 'Sports', 'Carry Lab', '2', 'Soccer', 'Soccer simulation focusing on the professional Japanese league.', 'Lead your chosen J. League club to the top of the standings.', 'A fast-paced 16-bit soccer title for the Japanese market.', 'J. League Champion Soccer offers smooth arcade-style football. Master the pitch and score incredible 16-bit goals in this polished Mega Drive sports game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('j-league-pro-striker-japan-v10', 'Genesis', 'J. League Pro Striker (Japan) (v1.0)', '1993', 'Sports', 'Carry Lab', '2', 'Soccer', 'Soccer simulation with official J. League licenses.', 'Manage your team and win the professional league title.', 'The first entry in the popular J. League Pro Striker series.', 'J. League Pro Striker brings authentic Japanese soccer to your console. Experience detailed 16-bit rosters and seasonal play on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('j-league-pro-striker-japan-v13', 'Genesis', 'J. League Pro Striker (Japan) (v1.3)', '1994', 'Sports', 'Carry Lab', '2', 'Soccer', 'Soccer simulation with official J. League licenses.', 'Manage your team and win the professional league title.', 'An updated revision (v1.3) of the original Pro Striker.', 'J. League Pro Striker (v1.3) offers refined 16-bit gameplay and updated rosters. Experience the growth of the J. League on your Sega Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('j-league-pro-striker-2-japan', 'Genesis', 'J. League Pro Striker 2 (Japan)', '1994', 'Sports', 'Carry Lab', '2', 'Soccer', 'Soccer simulation with improved graphics and gameplay.', 'Win the championship using refined tactics and new moves.', 'The feature-rich sequel to the J. League Pro Striker series.', 'J. League Pro Striker 2 features enhanced 16-bit visuals and deeper management. Take your club to glory in this definitive Japanese soccer sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('j-league-pro-striker-final-stage-japan', 'Genesis', 'J. League Pro Striker Final Stage (Japan)', '1995', 'Sports', 'Carry Lab', '2', 'Soccer', 'Soccer simulation focusing on the final matches of the season.', 'Overcome the final stage hurdles to claim the championship trophy.', 'A special edition of the Pro Striker series.', 'J. League Pro Striker Final Stage focuses on the high-stakes end-of-season drama. Master the 16-bit pitch in this intense Mega Drive sports title.');
