INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jack-nicklaus-power-challenge-golf-usa-europe', 'Genesis', 'Jack Nicklaus'' Power Challenge Golf (USA, Europe)', '1994', 'Sports', 'Sculptured Software', '2', 'Golf', 'Professional golf simulation with 3D-style course views.', 'Win the tournament by mastering the wind, clubs, and terrain.', 'A realistic golf game featuring the legendary Jack Nicklaus.', 'Jack Nicklaus'' Power Challenge Golf offers deep 16-bit simulation. Master your swing and conquer world-class courses in this detailed Sega sports title.');
