INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('james-pond-ii---codename-robocod-usa-europe', 'Genesis', 'James Pond II - Codename Robocod (USA, Europe)', '1991', 'Platformer', 'Vectordean', '1', 'Platformer', 'Side-scrolling platformer with a stretching mechanic.', 'Infiltrate Santa''s workshop to rescue the captured elves.', 'The definitive 16-bit version of the James Pond sequel.', 'James Pond II: Codename RoboCod is a masterpiece of 16-bit creativity. Stretch your way through imaginative levels in this highly-rated Sega Genesis classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jammit-usa', 'Genesis', 'Jammit (USA)', '1996', 'Sports', 'GTE Entertainment', '2', 'Basketball', 'Two-on-two street basketball with an urban theme.', 'Out-hustle and out-score your rivals in the playground.', 'A gritty and stylized 16-bit street hoops game.', 'Jammit brings the attitude of the street to your console. Master the 1-on-1 and 2-on-2 16-bit basketball mechanics in this unique Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('janou-touryuumon-japan', 'Genesis', 'Janou Touryuumon (Japan)', '1993', 'Puzzle', 'Unknown', '1', 'Puzzle', 'Mahjong simulation with a focus on competitive tournament play.', 'Defeat a series of skilled opponents to become the mahjong master.', 'A polished and professional 16-bit mahjong title.', 'Janou Touryuumon offers authentic mahjong gameplay on the Mega Drive. Master the tiles and outwit your rivals in this stylish Japanese simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jantei-monogatari-japan', 'Genesis', 'Jantei Monogatari (Japan)', '1991', 'Puzzle', 'Unknown', '1', 'Puzzle', 'Mahjong simulation mixed with adventure and story elements.', 'Solve mysteries and win matches to progress through the plot.', 'A unique blend of mahjong and adventure storytelling.', 'Jantei Monogatari offers a different take on the 16-bit board game. Experience a detailed plot alongside classic mahjong matches on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jashin-draxos-japan', 'Genesis', 'Jashin Draxos (Japan)', '1991', 'Action', 'Naxat Soft', '1', 'Action', 'Side-scrolling action brawler with a dark fantasy theme.', 'Battle through demonic hordes to defeat the god Draxos.', 'A dark and atmospheric 16-bit action game (Lord of Sword).', 'Jashin Draxos (Lord of Sword) features challenging combat and impressive 16-bit art. Journey through a dangerous mythic world on your Sega Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jelly-boy-europe-proto', 'Genesis', 'Jelly Boy (Europe) (Proto)', '1995', 'Platformer', 'Probe Entertainment', '1', 'Platformer', 'Side-scrolling platformer with a shape-shifting protagonist.', 'Transform into different objects to solve puzzles and reach the goal.', 'An unreleased 16-bit prototype of the SNES classic.', 'Jelly Boy brings its unique "morphing" gameplay to the Genesis. Experience rare 16-bit platforming as you transform to overcome various obstacles in this prototype.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jennifer-capriati-tennis-usa', 'Genesis', 'Jennifer Capriati Tennis (USA)', '1994', 'Sports', 'BlueSky Software', '2', 'Tennis', 'Realistic tennis simulation with top-down and isometric views.', 'Rise through the world rankings to win the Grand Slam.', 'A polished tennis sim featuring the 90s tennis star.', 'Jennifer Capriati Tennis (GrandSlam ''92) brings professional 16-bit court action to the Genesis. Master various surfaces like clay and grass in this detailed Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeopardy!-usa', 'Genesis', 'Jeopardy! (USA)', '1992', 'Trivia', 'GameTek', '2', 'Quiz', 'Digital trivia game based on the famous television show.', 'Outscore your opponents by providing questions for given answers.', 'A faithful 16-bit adaptation of the hit game show.', 'Jeopardy! on the Genesis captures the atmosphere of the TV classic. Test your knowledge across hundreds of categories in this engaging 16-bit trivia challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeopardy!-deluxe-usa', 'Genesis', 'Jeopardy! Deluxe (USA)', '1993', 'Trivia', 'GameTek', '2', 'Quiz', 'Digital trivia game with an expanded question database.', 'Outscore your opponents and win the "Tournament of Champions."', 'An upgraded version of the original Jeopardy! title.', 'Jeopardy! Deluxe offers thousands of new questions and refined 16-bit presentation. Experience the ultimate game show challenge on your Sega console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeopardy!-sports-edition-usa', 'Genesis', 'Jeopardy! Sports Edition (USA)', '1994', 'Trivia', 'GameTek', '2', 'Quiz', 'Digital trivia game focused entirely on athletic history.', 'Prove your sports knowledge to win the championship game.', 'A specialized sports-themed edition of Jeopardy!', 'Jeopardy! Sports Edition tests your 16-bit athletic IQ. From baseball stats to Olympic history, dominate the scoreboard in this competitive Sega trivia game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jerry-glanvilles-pigskin-footbrawl-usa', 'Genesis', 'Jerry Glanville''s Pigskin Footbrawl (USA)', '1991', 'Action', 'Beam Software', '2', 'Action', 'Combat-heavy American football with a medieval/fantasy twist.', 'Score touchdowns while using weapons to incapacitate rivals.', 'A brutal and humorous take on arcade football.', 'Jerry Glanville''s Pigskin Footbrawl is "medieval football" at its finest. Use maces and traps to clear a path to the endzone in this chaotic 16-bit Sega brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jet-in-sonic-3-&-knuckles', 'Genesis', 'Jet in Sonic 3 & Knuckles', '1994', 'Action', 'Sonic Team', '1', 'Action', 'High-speed platforming featuring the legendary Hawk rival.', 'Navigate classic Sonic stages with Jet''s unique physics.', 'A character-swap mod bringing the Sonic Riders star to 16-bit.', 'Jet in Sonic 3 & Knuckles lets you play as the leader of the Babylon Rogues. Experience the 16-bit masterpiece with custom-built Jet the Hawk sprites and mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jewel-master-world', 'Genesis', 'Jewel Master (World)', '1991', 'Puzzle', 'Western Technologies', '1', 'Puzzle', 'Side-scrolling action with a focus on elemental ring magic.', 'Collect 12 elemental rings to defeat the Demon King, Jardine.', 'A dark fantasy action game with deep customization.', 'Jewel Master features a unique magic system where you combine rings for different attacks. Explore a gritty 16-bit world and defeat massive bosses in this Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jewel-master-world-rev-a', 'Genesis', 'Jewel Master (World) (Rev A)', '1991', 'Puzzle', 'Western Technologies', '1', 'Puzzle', 'Side-scrolling action with a focus on elemental ring magic.', 'Collect 12 elemental rings to defeat the Demon King, Jardine.', 'An updated revision (Rev A) of the elemental action game.', 'Jewel Master features a unique magic system where you combine rings for different attacks. Explore a gritty 16-bit world and defeat massive bosses in this Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jimmy-whites-whirlwind-snooker-europe', 'Genesis', 'Jimmy White''s Whirlwind Snooker (Europe)', '1991', 'Sports', 'Teque London', '2', 'Sports', 'Realistic 3D-perspective snooker simulation.', 'Clear the table and defeat the "Whirlwind" himself, Jimmy White.', 'A technically impressive and physics-heavy snooker sim.', 'Jimmy White''s Whirlwind Snooker brings professional 16-bit billiards home. Experience realistic ball physics and a unique "eye-ball" camera in this polished Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jiuji-majiang-ii---lengyan-pian-china-unl', 'Genesis', 'Jiuji Majiang II - Lengyan Pian (China) (Unl)', '1994', 'Board Game', 'Unknown', '4', 'Mahjong', 'Mahjong simulation with a focus on competitive play.', 'Master the tiles to defeat opponents in a high-stakes tournament.', 'A rare unlicensed 16-bit mahjong title from China.', 'Jiuji Majiang II offers authentic mahjong gameplay with unique custom 16-bit graphics. Challenge the masters in this rare and unofficial Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-&-mac-usa', 'Genesis', 'Joe & Mac (USA)', '1991', 'Platformer', 'Data East', '2', 'Platformer', 'Side-scrolling platformer featuring prehistoric combat.', 'Rescue the "Cave Babes" from a rival tribe of cavemen.', 'A colorful and wacky "Caveman Ninja" action game.', 'Joe & Mac brings prehistoric 16-bit fun to the Genesis. Battle dinosaurs and rival tribes with boomerangs and bones in this classic arcade-to-home port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-montana-football-world', 'Genesis', 'Joe Montana Football (World)', '1991', 'Sports', 'BlueSky Software', '4', 'Football', 'Top-down American football simulation.', 'Lead your team to victory and win the Sega Bowl.', 'The foundational football title featuring the legendary QB.', 'Joe Montana Football delivers accessible 16-bit gridiron action. Master the "Montana choice" plays and dominate the field in this essential Sega sports game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-montana-ii-sports-talk-football-world', 'Genesis', 'Joe Montana II Sports Talk Football (World)', '1992', 'Sports', 'BlueSky Software', '4', 'Football', 'Side-scrolling football with "Sports Talk" voice synthesis.', 'Win the championship while listening to real-time commentary.', 'A revolutionary sports game with digitized speech.', 'Joe Montana II Sports Talk Football changed the game with live 16-bit commentary. Experience the atmosphere of a real broadcast on your Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-montana-ii-sports-talk-football-world-rev-a', 'Genesis', 'Joe Montana II Sports Talk Football (World) (Rev A)', '1992', 'Sports', 'BlueSky Software', '4', 'Football', 'Side-scrolling football with "Sports Talk" voice synthesis.', 'Win the championship while listening to real-time commentary.', 'An updated revision (Rev A) of the Sports Talk sequel.', 'Joe Montana II Sports Talk Football changed the game with live 16-bit commentary. Experience the atmosphere of a real broadcast on your Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('john-madden-football---pro-football-japan', 'Genesis', 'John Madden Football - Pro Football (Japan)', '1991', 'Sports', 'Electronic Arts', '4', 'Football', 'Isometric American football with professional strategy.', 'Master the playbook to win the inaugural 16-bit championship.', 'The Japanese release of the original Madden hit.', 'John Madden Football (Japan) brings the legendary NFL simulation to the Mega Drive. Experience the birth of the 16-bit sports dynasty with authentic plays and logic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('john-madden-football-92-usa-europe', 'Genesis', 'John Madden Football ''92 (USA, Europe)', '1991', 'Sports', 'Electronic Arts', '4', 'Football', 'Isometric American football with refined graphics and AI.', 'Lead your team through a full season to win the Super Bowl.', 'The second Madden title, featuring improved 16-bit physics.', 'John Madden Football ''92 introduced the "ambulance" and deeper stats. Experience the definitive 16-bit football experience with updated rosters and gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('john-madden-football-93---championship-edition-usa', 'Genesis', 'John Madden Football ''93 - Championship Edition (USA)', '1992', 'Sports', 'Electronic Arts', '4', 'Football', 'Isometric American football featuring history''s best teams.', 'Compete in a tournament of champions with legendary squads.', 'A special edition focusing on the greatest teams in history.', 'John Madden Football ''93: Championship Edition lets you play as the all-time greats. Master the 16-bit gridiron with iconic historical rosters on your Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('john-madden-football-93-usa-europe', 'Genesis', 'John Madden Football ''93 (USA, Europe)', '1992', 'Sports', 'Electronic Arts', '4', 'Football', 'Isometric American football with updated plays and logic.', 'Win the championship with refined 16-bit tactical options.', 'The third installment of the blockbuster Madden series.', 'John Madden Football ''93 features more animations and a deeper playbook. Experience the height of 16-bit football simulation on the Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('john-madden-football-usa-europe', 'Genesis', 'John Madden Football (USA, Europe)', '1990', 'Sports', 'Electronic Arts', '4', 'Football', 'Isometric American football with professional strategy.', 'Master the playbook to win the inaugural 16-bit championship.', 'The game that launched the most successful sports franchise.', 'John Madden Football defined the 16-bit sports era. Master the isometric view and realistic playbooks in this quintessential Sega Genesis classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jordan-vs-bird---one-on-one-japan', 'Genesis', 'Jordan Vs Bird - One on One (Japan)', '1991', 'Sports', 'Electronic Arts', '2', 'Basketball', 'One-on-one basketball with legendary NBA superstars.', 'Outplay your rival in a head-to-head match or skills contest.', 'A high-profile 16-bit duel between two icons.', 'Jordan Vs Bird features the "Slam Dunk" and "Three Point" contests. Master the 16-bit court with Michael Jordan or Larry Bird in this classic Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jordan-vs-bird-usa-europe', 'Genesis', 'Jordan Vs Bird (USA, Europe)', '1991', 'Sports', 'Electronic Arts', '2', 'Basketball', 'One-on-one basketball with legendary NBA superstars.', 'Outplay your rival in a head-to-head match or skills contest.', 'The North American release of the superstar b-ball duel.', 'Jordan Vs Bird features the "Slam Dunk" and "Three Point" contests. Master the 16-bit court with Michael Jordan or Larry Bird in this classic Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jordan-vs-bird-usa-europe-v11', 'Genesis', 'Jordan Vs Bird (USA, Europe) (v1.1)', '1991', 'Sports', 'Electronic Arts', '2', 'Basketball', 'One-on-one basketball with legendary NBA superstars.', 'Outplay your rival in a head-to-head match or skills contest.', 'An updated revision (v1.1) of the superstar basketball game.', 'Jordan Vs Bird features the "Slam Dunk" and "Three Point" contests. Master the 16-bit court with Michael Jordan or Larry Bird in this classic Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joshua-&-the-battle-of-jericho-usa-unl', 'Genesis', 'Joshua & The Battle of Jericho (USA) (Unl)', '1991', 'Adventure', 'Wisdom Tree', '1', 'Adventure', 'Tile-based action puzzle game with a biblical theme.', 'Pillage the city of Jericho and answer Bible trivia to progress.', 'A rare unlicensed Christian game from Wisdom Tree.', 'Joshua & The Battle of Jericho offers unique puzzle-solving and quiz mechanics. Navigate 100 levels of 16-bit biblical action in this rare unofficial title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('judge-dredd-usa-beta', 'Genesis', 'Judge Dredd (USA) (Beta)', '1994', 'Action', 'Probe Entertainment', '1', 'Action', 'Side-scrolling run-and-gun with platforming elements.', 'Clean up the streets of Mega-City One and stop the Dark Judges.', 'A beta development build of the Judge Dredd movie game.', 'Explore early level layouts and weapon mechanics in the Judge Dredd Beta. A rare look at the development of this gritty 16-bit comic book action game.');
