INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('judge-dredd-world', 'Genesis', 'Judge Dredd (World)', '1995', 'Action', 'Probe Entertainment', '1', 'Action', 'Side-scrolling run-and-gun with platforming elements.', 'Clean up the streets of Mega-City One and stop the Dark Judges.', 'The definitive 16-bit adaptation of the comic and film.', 'Judge Dredd features explosive 16-bit combat and cinematic stages. Use the Lawgiver to bring justice to the wasteland in this challenging Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('juju-densetsu-japan', 'Genesis', 'JuJu Densetsu (Japan)', '1991', 'Action', 'Nippon Dexter', '1', 'Action', 'Side-scrolling platformer featuring a spit-attacking ape.', 'Defeat the wizard Vookimedlo to regain your human form.', 'The Japanese Mega Drive version of the arcade hit "Toki."', 'JuJu Densetsu (Toki) is a 16-bit action classic. Master the unique spit-attacks and navigate dangerous jungles in this charming and difficult Sega port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('junction-japan-usa', 'Genesis', 'Junction (Japan, USA)', '1990', 'Puzzle', 'Micronics', '2', 'Puzzle', 'Isometric puzzle game with sliding-track mechanics.', 'Align the tracks to guide a rolling ball to the exit.', 'A creative and challenging 16-bit logic puzzle.', 'Junction features 50 levels of mind-bending track manipulation. Master the timing and 16-bit perspective in this unique and addictive Sega puzzle game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-book-the-europe', 'Genesis', 'Jungle Book, The (Europe)', '1994', 'Platformer', 'Virgin Interactive', '1', 'Platformer', 'Side-scrolling platformer featuring Disney''s Mowgli.', 'Collect gems and find your friends to escape the jungle.', 'A visually stunning Disney adventure from Virgin.', 'The Jungle Book features incredible 16-bit animation and massive levels. Swing through the trees and defeat Shere Khan in this classic Sega platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-book-the-usa', 'Genesis', 'Jungle Book, The (USA)', '1994', 'Platformer', 'Virgin Interactive', '1', 'Platformer', 'Side-scrolling platformer featuring Disney''s Mowgli.', 'Collect gems and find your friends to escape the jungle.', 'The North American release of the lush Disney adventure.', 'The Jungle Book features incredible 16-bit animation and massive levels. Swing through the trees and defeat Shere Khan in this classic Sega platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-strike---uketsugareta-kyouki-japan', 'Genesis', 'Jungle Strike - Uketsugareta Kyouki (Japan)', '1993', 'Action', 'Electronic Arts', '1', 'Action', 'Isometric helicopter combat with strategic resource management.', 'Thwart a nuclear threat by completing various tactical missions.', 'The Japanese Mega Drive version of the Strike sequel.', 'Jungle Strike - Uketsugareta Kyouki brings intense 16-bit aerial warfare to the Mega Drive. Command multiple vehicles to stop a global crisis in this acclaimed tactical sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-strike-usa-europe', 'Genesis', 'Jungle Strike (USA, Europe)', '1993', 'Action', 'Electronic Arts', '1', 'Action', 'Isometric helicopter combat with strategic resource management.', 'Thwart a nuclear threat by completing various tactical missions.', 'The definitive 16-bit sequel to Desert Strike.', 'Jungle Strike features expanded missions and new vehicles like the hovercraft. Master the 16-bit skies and protect Washington D.C. in this quintessential Sega action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-strike-usa-beta', 'Genesis', 'Jungle Strike (USA) (Beta)', '1993', 'Action', 'Electronic Arts', '1', 'Action', 'Isometric helicopter combat with strategic resource management.', 'Thwart a nuclear threat by completing various tactical missions.', 'A beta development build of Jungle Strike.', 'Explore early mission parameters and vehicle handling in the Jungle Strike Beta. A fascinating look at the development of this 16-bit tactical masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park---rampage-edition-usa-europe', 'Genesis', 'Jurassic Park - Rampage Edition (USA, Europe)', '1994', 'Action', 'BlueSky Software', '2', 'Action', 'Side-scrolling run-and-gun with a focus on high-octane action.', 'Survive Isla Nublar as Grant or hunt humans as a Raptor.', 'An action-heavy follow-up to the original 16-bit hit.', 'Jurassic Park: Rampage Edition ramps up the 16-bit intensity. Choose your species and battle through chaos in this explosive and refined Sega Genesis adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-europe', 'Genesis', 'Jurassic Park (Europe)', '1993', 'Action', 'Ocean Software', '1', 'Action', 'Hybrid of side-scrolling action and top-down exploration.', 'Complete missions to restore power and escape the park.', 'The European release of the cinematic movie tie-in.', 'Jurassic Park on the Genesis offers a unique dual-perspective experience. Play as Dr. Grant or a Velociraptor in this atmospheric and groundbreaking 16-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-japan', 'Genesis', 'Jurassic Park (Japan)', '1993', 'Action', 'Ocean Software', '1', 'Action', 'Hybrid of side-scrolling action and top-down exploration.', 'Complete missions to restore power and escape the park.', 'The Japanese Mega Drive version of the Jurassic Park hit.', 'Jurassic Park brings the blockbuster film to the Mega Drive. Master the 16-bit platforming and survival mechanics in this high-quality Sega adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-usa', 'Genesis', 'Jurassic Park (USA)', '1993', 'Action', 'Ocean Software', '1', 'Action', 'Hybrid of side-scrolling action and top-down exploration.', 'Complete missions to restore power and escape the park.', 'The North American release of the iconic dinosaur survival game.', 'Jurassic Park on the Genesis offers a unique dual-perspective experience. Play as Dr. Grant or a Velociraptor in this atmospheric and groundbreaking 16-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-usa-beta', 'Genesis', 'Jurassic Park (USA) (Beta)', '1993', 'Action', 'Ocean Software', '1', 'Action', 'Hybrid of side-scrolling action and top-down exploration.', 'Complete missions to restore power and escape the park.', 'A beta development version of the Jurassic Park game.', 'Witness the evolution of 16-bit dinosaurs in the Jurassic Park Beta. Explore early level designs and character physics in this rare Sega Genesis prototype.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-2---the-lost-world-usa-europe', 'Genesis', 'Jurassic Park 2 - The Lost World (USA, Europe)', '1997', 'Action', 'Appaloosa Interactive', '2', 'Action', 'Isometric action-adventure with base-building and strategy.', 'Capture dinosaurs and stop the bio-engineers on Isla Sorna.', 'A technically impressive isometric sequel (The Lost World).', 'Jurassic Park 2: The Lost World features some of the best 16-bit visuals on the Genesis. Navigate the island and use advanced gear to survive the prehistoric threat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('justice-league-task-force-world', 'Genesis', 'Justice League Task Force (World)', '1995', 'Fighting', 'Blizzard Entertainment', '2', 'Fighting', 'One-on-one fighting game featuring iconic DC superheroes.', 'Defeat a robotic duplicate of the League to save the world.', 'A competitive fighter starring Batman, Superman, and more.', 'Justice League Task Force brings DC''s finest to the 16-bit arena. Master unique special moves and fight for justice in this cinematic Sega brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('juuouki-japan', 'Genesis', 'Juuouki (Japan)', '1989', 'Action', 'Sega', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up with a mythological transformation mechanic.', 'Rescue Athena by transforming into powerful mythical beasts.', 'The original Japanese version of Altered Beast.', 'Juuouki is a 16-bit landmark. "Rise from your grave" and master the power of the wolf, dragon, and bear in this quintessential Mega Drive classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('juuouki-japan-v11', 'Genesis', 'Juuouki (Japan) (v1.1)', '1989', 'Action', 'Sega', '2', 'Beat ''em Up', 'Side-scrolling beat ''em up with a mythological transformation mechanic.', 'Rescue Athena by transforming into powerful mythical beasts.', 'An updated revision (v1.1) of the Japanese classic.', 'Juuouki (Altered Beast) remains a definitive 16-bit experience. Battle through the underworld and unleash your inner beast in this polished Sega brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ka-ge-ki---fists-of-steel-usa', 'Genesis', 'Ka-Ge-Ki - Fists of Steel (USA)', '1990', 'Fighting', 'Konami', '2', 'Fighting', 'Top-down brawling with a focus on arena-style combat.', 'Defeat a gauntlet of street fighters to win the tournament.', 'A gritty arcade-style fighter (Fists of Steel).', 'Ka-Ge-Ki brings unique top-down 16-bit brawling to the Genesis. Master the timing of your punches and outlast every rival in the ring.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ka-ge-ki-japan', 'Genesis', 'Ka-Ge-Ki (Japan)', '1990', 'Fighting', 'Konami', '2', 'Fighting', 'Top-down brawling with a focus on arena-style combat.', 'Defeat a gauntlet of street fighters to win the tournament.', 'The original Japanese release of the arena brawler.', 'Ka-Ge-Ki features intense 1-on-1 combat with a unique perspective. Experience the gritty 16-bit arcade action on your Sega Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaizo-sonic-2-demo', 'Genesis', 'Kaizo Sonic 2 (Demo)', '2010', 'Platformer', 'Fan Made', '1', 'Platformer', 'High-speed platforming with extreme "Kaizo" difficulty.', 'Navigate incredibly difficult versions of Sonic 2 stages.', 'A demo of a high-difficulty fan-made Sonic 2 mod.', 'Kaizo Sonic 2 is built for masters of 16-bit platforming. Face near-impossible traps and pixel-perfect jumps in this intense Sega Genesis challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaizo-sonic-the-hedgehog---the-rage-game', 'Genesis', 'Kaizo Sonic The Hedgehog - The RAGE game', '2010', 'Platformer', 'Fan Made', '1', 'Platformer', 'High-speed platforming with extreme "Kaizo" difficulty.', 'Survive the most punishing Sonic levels ever designed.', 'A "Rage" focused high-difficulty mod for Sonic 1.', 'Kaizo Sonic The Hedgehog pushes 16-bit skill to the absolute limit. Prepare for a grueling test of patience and precision in this legendary fan creation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawasaki-superbike-challenge-usa-europe', 'Genesis', 'Kawasaki Superbike Challenge (USA, Europe)', '1995', 'Racing', 'Lankhor', '2', 'Racing', 'Realistic motorcycle racing with 3D-style sprite scaling.', 'Win the international championship across various circuits.', 'A high-speed and technical racing simulation.', 'Kawasaki Superbike Challenge offers blistering 16-bit speed. Master the leaning mechanics and outpace the field in this polished Sega racing sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawasaki-superbike-challenge-usa-beta', 'Genesis', 'Kawasaki Superbike Challenge (USA) (Beta)', '1995', 'Racing', 'Lankhor', '2', 'Racing', 'Realistic motorcycle racing with 3D-style sprite scaling.', 'Win the international championship across various circuits.', 'A beta development build of the Kawasaki racer.', 'Peek into the tuning of 16-bit motorcycle physics with the Kawasaki Superbike Challenge Beta. A rare look at the development of this fast-paced Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kcs-sonic-1-revamped', 'Genesis', 'KC''s Sonic 1 Revamped', '2015', 'Platformer', 'Fan Made', '1', 'Platformer', 'High-speed platforming with modernized level layouts.', 'Explore a fresh take on South Island with new paths and secrets.', 'A comprehensive "Revamped" overhaul of the first Sonic game.', 'KC''s Sonic 1 Revamped breathes new life into the 16-bit classic. Experience refined level design and updated mechanics in this high-quality fan mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kick-boxing-the-japan', 'Genesis', 'Kick Boxing, The (Japan)', '1992', 'Fighting', 'Sims', '2', 'Fighting', 'One-on-one kickboxing simulation with a side-view.', 'Rise through the ranks of the professional kickboxing world.', 'A realistic 16-bit martial arts sports title.', 'The Kick Boxing offers technical 16-bit combat. Master your strikes and blocks to become the world champion in this polished Mega Drive simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kick-off-3---european-challenge-europe', 'Genesis', 'Kick Off 3 - European Challenge (Europe)', '1994', 'Sports', 'Anco', '4', 'Soccer', 'Soccer simulation with a focus on speed and overhead view.', 'Lead your team to victory in the European championship.', 'A fast-paced 16-bit entry in the Kick Off series.', 'Kick Off 3: European Challenge features high-speed football and intuitive controls. Master the pitch in this classic European Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kid-chameleon-usa-europe', 'Genesis', 'Kid Chameleon (USA, Europe)', '1992', 'Platformer', 'Sega', '1', 'Platformer', 'Side-scrolling platformer with a mask-based power system.', 'Use over 10 different masks to rescue your friends from a VR game.', 'A massive and challenging 16-bit platforming masterpiece.', 'Kid Chameleon is one of the largest games on the Genesis. Transform into a samurai, knight, or tank to navigate over 100 levels of 16-bit action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kidou-keisatsu-patlabor---98-shiki-kidou-seyo!-japan', 'Genesis', 'Kidou Keisatsu Patlabor - 98-Shiki Kidou Seyo! (Japan)', '1992', 'Strategy', 'Bec', '1', 'Strategy', 'Tactical adventure game based on the iconic mecha anime.', 'Lead the Special Vehicles Section 2 to solve mecha-related crimes.', 'A beautifully animated Japanese adventure game.', 'Kidou Keisatsu Patlabor brings the anime''s world to the Mega Drive. Experience deep 16-bit storytelling and strategic investigations in this rare title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('killing-game-show-the-japan', 'Genesis', 'Killing Game Show, The (Japan)', '1991', 'Action', 'Scitron', '1', 'Action', 'Top-down arena shooter with puzzle and rescue elements.', 'Navigate dangerous mechanical arenas to rescue survivors.', 'The Japanese Mega Drive version of Fatal Rewind.', 'The Killing Game Show offers high-intensity 16-bit shooting and puzzle-solving. Survive the deadly traps and escape the arena on your Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-fighters-98-the-unl', 'Genesis', 'King of Fighters ''98, The (Unl)', '1998', 'Fighting', 'SNK', '2', 'Fighting', 'One-on-one fighting game with a massive roster.', 'Win the King of Fighters tournament using 3-on-3 tag teams.', 'A rare and impressive unlicensed 16-bit port of KOF ''98.', 'The King of Fighters ''98 (Unl) brings the SNK legend to the Genesis hardware. Experience a unique "bootleg" take on the classic 3-on-3 brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-the-monsters-europe', 'Genesis', 'King of the Monsters (Europe)', '1991', 'Fighting', 'SNK', '2', 'Fighting', 'One-on-one fighting game featuring giant monsters.', 'Battle across cityscapes to prove you are the strongest kaiju.', 'A 16-bit port of the SNK arcade wrestling hit.', 'King of the Monsters brings massive monster brawling to your console. Destroy cities and pin your rivals in this unique and destructive 16-bit fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-the-monsters-usa', 'Genesis', 'King of the Monsters (USA)', '1991', 'Fighting', 'SNK', '2', 'Fighting', 'One-on-one fighting game featuring giant monsters.', 'Battle across cityscapes to prove you are the strongest kaiju.', 'The North American release of the kaiju brawler.', 'King of the Monsters brings massive monster brawling to your console. Destroy cities and pin your rivals in this unique and destructive 16-bit fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-the-monsters-2-usa', 'Genesis', 'King of the Monsters 2 (USA)', '1992', 'Fighting', 'SNK', '2', 'Fighting', 'Side-scrolling beat ''em up featuring giant monsters.', 'Fight through city streets to stop a global alien invasion.', 'The action-packed 16-bit sequel to King of the Monsters.', 'King of the Monsters 2 shifts the focus to high-energy 16-bit brawling. Battle massive alien bio-beasts and save the Earth on your Sega Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madou-monogatari-i-english-translation', 'Genesis', 'Madou Monogatari I (English Translation)', '1993', 'RPG', 'Compile', '1', 'RPG', 'First-person dungeon crawler RPG with a cute aesthetic.', 'Guide Arle Nadja through the magic school''s graduation tower.', 'An English fan translation of the iconic Japanese RPG.', 'Madou Monogatari I is a 16-bit RPG gem. Experience the origin of the Puyo Puyo characters in this charming and mechanically unique dungeon crawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madou-monogatari-i-japan', 'Genesis', 'Madou Monogatari I (Japan)', '1993', 'RPG', 'Compile', '1', 'RPG', 'First-person dungeon crawler RPG with a cute aesthetic.', 'Guide Arle Nadja through the magic school''s graduation tower.', 'The original Japanese release of the magic school RPG.', 'Madou Monogatari I features a unique status system and vibrant 16-bit art. Explore the graduation tower in this classic Mega Drive dungeon crawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-school-bus-the-usa', 'Genesis', 'Magic School Bus, The (USA)', '1994', 'Educational', 'Media Station', '1', 'Educational', 'Educational adventure game based on the popular TV show.', 'Explore the solar system and learn about science with Ms. Frizzle.', 'A fun and interactive 16-bit educational journey.', 'The Magic School Bus brings science to the Genesis! Travel through space and solve puzzles in this engaging and colorful 16-bit educational title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-hat-no-buttobi-turbo!-daibouken-japan', 'Genesis', 'Magical Hat no Buttobi Turbo! Daibouken (Japan)', '1990', 'Platformer', 'SEGA', '1', 'Platformer', 'Side-scrolling platformer with a focus on speed and gadgets.', 'Rescue your friends and defeat the evil Ji-Goku.', 'The Japanese precursor to Decap Attack.', 'Magical Hat no Buttobi Turbo! Daibouken offers high-energy 16-bit platforming based on the anime. Experience the original colorful levels and unique mechanics on the Mega Drive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-taruruuto-kun-japan', 'Genesis', 'Magical Taruruuto-kun (Japan)', '1991', 'Action', 'TOSE', '1', 'Action', 'Side-scrolling platformer with magic and puzzle elements.', 'Help Taruruuto-kun complete his magical training and save the day.', 'A visually stunning and creative Game Freak masterpiece.', 'Magical Taruruuto-kun is one of the most beautiful games on the Mega Drive. Use magic to manipulate objects in this charming and highly-regarded 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-cop-ryuu---shiro-ookami-no-yabou-japan', 'Genesis', 'Mahjong Cop Ryuu - Shiro Ookami no Yabou (Japan)', '1990', 'Board Game', 'Namco', '2', 'Mahjong', 'Mahjong simulation with adventure and investigation elements.', 'Use mahjong skills to solve crimes and defeat the White Wolf.', 'A unique 16-bit "detective mahjong" hybrid.', 'Mahjong Cop Ryuu combines traditional 16-bit tiles with an engaging story. Track down criminals and win matches in this stylish Japanese Mega Drive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-lover-china-unl', 'Genesis', 'Mahjong Lover (China) (Unl)', '1994', 'Board Game', 'Unknown', '4', 'Mahjong', 'Traditional Mahjong simulation for competitive play.', 'Defeat a variety of opponents to prove your mahjong mastery.', 'A rare unlicensed 16-bit Mahjong game from China.', 'Mahjong Lover (Unl) offers a straightforward and accessible mahjong experience. Enjoy classic 16-bit tile play in this rare unofficial Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('majiang-emo-ta---devilish-mahjong-tower-china-unl', 'Genesis', 'Majiang E''mo Ta - Devilish Mahjong Tower (China) (Unl)', '1994', 'Board Game', 'Unknown', '4', 'Mahjong', 'Tile-matching puzzle game with a tower-climbing theme.', 'Clear the demonic tower by matching tiles and solving puzzles.', 'An unlicensed 16-bit Mahjong-style puzzle game.', 'Majiang E''mo Ta (Devilish Mahjong Tower) features a dark aesthetic and challenging logic. Ascend the tower in this unique unofficial 16-bit Sega title.');
