INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-fangs-japan', 'Genesis', 'Metal Fangs (Japan)', '1995', 'Action', 'ISI', '1', 'Action', 'Futuristic top-down combat racing with custom vehicles.', 'Destroy rivals and win the race using a variety of weapons.', 'A gritty and technical mecha-racing game.', 'Metal Fangs delivers intense 16-bit vehicular combat. Customize your racer and blast through opponents in this unique Japanese Mega Drive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-sonic-hyperdrive', 'Genesis', 'Metal Sonic Hyperdrive', '2007', 'Platformer', 'Fan Made', '1', 'Platformer', 'High-speed platforming with a custom robotic protagonist.', 'Complete a massive overhaul of Sonic the Hedgehog as Metal Sonic.', 'A legendary and highly polished fan-made Sonic total conversion.', 'Metal Sonic Hyperdrive features new zones, music, and gameplay mechanics. Experience 16-bit speed from a robotic perspective in this top-tier Sega mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-sonic-hyperdrive-2011', 'Genesis', 'Metal Sonic Hyperdrive (2011)', '2011', 'Platformer', 'Fan Made', '1', 'Platformer', 'High-speed platforming with a custom robotic protagonist.', 'Navigate the early 2011 build of the Hyperdrive project.', 'The original release of the Metal Sonic Hyperdrive mod.', 'Metal Sonic Hyperdrive (2011) is the foundation of the robotic saga. Explore the early level designs of this landmark 16-bit Sega modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-sonic-in-sonic-the-hedgehog', 'Genesis', 'Metal Sonic in Sonic the Hedgehog', '1993', 'Platformer', 'Fan Made', '1', 'Platformer', 'High-speed platforming as the robotic doppelganger.', 'Conquer the original South Island levels using Metal Sonic.', 'A character-swap mod for the first Sonic game.', 'Metal Sonic in Sonic the Hedgehog brings the rival robot to the 16-bit origin story. Enjoy custom sprites and a cold, mechanical feel in this Sega mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-sonic-in-sonic-the-hedgehog-2', 'Genesis', 'Metal Sonic in Sonic the Hedgehog 2', '1994', 'Platformer', 'Fan Made', '1', 'Platformer', 'High-speed platforming as the robotic doppelganger.', 'Race through West Side Island with Metal Sonic''s unique flair.', 'A character-swap mod for the legendary Sonic 2.', 'Metal Sonic in Sonic 2 lets you pilot the metal menace through the sequel''s iconic loops. A perfect 16-bit mod for fans of the robotic rival.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-sonic-in-sonic-the-hedgehog-3-&-knuckles', 'Genesis', 'Metal Sonic in Sonic the Hedgehog 3 & Knuckles', '1994', 'Platformer', 'Fan Made', '1', 'Platformer', 'High-speed platforming as the robotic doppelganger.', 'Master Angel Island with the power of Metal Sonic.', 'A character-swap mod for the massive Sonic 3 & Knuckles.', 'Metal Sonic in Sonic 3 & Knuckles offers a robotic twist to the ultimate adventure. Navigate the 16-bit masterwork with custom metal sprites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-sonic-rebooted', 'Genesis', 'Metal Sonic Rebooted', '2016', 'Platformer', 'Fan Made', '1', 'Platformer', 'High-speed platforming with an overhauled moveset.', 'Conquer specialized stages with a "rebooted" Metal Sonic.', 'A mechanical and visual overhaul of the Metal Sonic engine.', 'Metal Sonic Rebooted features incredible 16-bit speed and modern gameplay tweaks. Experience a fresh challenge in this high-quality Sega fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-sonic-rebooted-shc2017', 'Genesis', 'Metal Sonic Rebooted SHC2017', '2017', 'Platformer', 'Fan Made', '1', 'Platformer', 'High-speed platforming with an overhauled moveset.', 'Navigate the 2017 contest version of the Rebooted mod.', 'The SHC 2017 edition of the Metal Sonic project.', 'Metal Sonic Rebooted SHC2017 offers a glimpse into the evolution of this 16-bit mod. Experience refined physics and custom level layouts on the Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-sonics-challenge', 'Genesis', 'Metal Sonic''s Challenge', '2015', 'Platformer', 'Fan Made', '1', 'Platformer', 'High-speed platforming focused on precision and time.', 'Complete a gauntlet of challenging levels as Metal Sonic.', 'A specialized "challenge" mod for the Sonic engine.', 'Metal Sonic''s Challenge pushes 16-bit skills to the limit. Master the robotic physics to beat the clock in this intense Sega fan creation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('michael-jacksons-moonwalker-world', 'Genesis', 'Michael Jackson''s Moonwalker (World)', '1990', 'Action', 'Sega', '2', 'Action', 'Side-scrolling action-brawler based on the hit film.', 'Use dance moves and magic to rescue kidnapped children.', 'A cinematic masterpiece starring the King of Pop.', 'Michael Jackson''s Moonwalker is a 16-bit icon. Use the "Star Magic" and dance-fighting mechanics to defeat Mr. Big in this quintessential Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('michael-jacksons-moonwalker-world-rev-a', 'Genesis', 'Michael Jackson''s Moonwalker (World) (Rev A)', '1990', 'Action', 'Sega', '2', 'Action', 'Side-scrolling action-brawler based on the hit film.', 'Use dance moves and magic to rescue kidnapped children.', 'An updated revision (Rev A) of the Moonwalker hit.', 'Michael Jackson''s Moonwalker remains a classic of 16-bit style. Rescue the kids and master the smooth criminal combat in this polished Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mick-&-mack-as-the-global-gladiators-usa', 'Genesis', 'Mick & Mack as the Global Gladiators (USA)', '1992', 'Platformer', 'Virgin Interactive', '1', 'Platformer', 'Side-scrolling run-and-gun with environmental themes.', 'Clean up the toxic world and reach the end of the stage.', 'A vibrant platformer featuring the McDonald''s mascots.', 'Global Gladiators (Mick & Mack) features incredible 16-bit animation. Blast away pollution in this high-quality and fast-paced Sega action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mick-&-mack-as-the-global-gladiators-usa-beta', 'Genesis', 'Mick & Mack as the Global Gladiators (USA) (Beta)', '1992', 'Platformer', 'Virgin Interactive', '1', 'Platformer', 'Side-scrolling run-and-gun with environmental themes.', 'Clean up the toxic world and reach the end of the stage.', 'A beta development build of the Global Gladiators game.', 'Explore early level physics and sprite work in the Global Gladiators Beta. A fascinating look at the development of this 16-bit Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-mania---the-timeless-adventures-of-mickey-mouse-europe', 'Genesis', 'Mickey Mania - The Timeless Adventures of Mickey Mouse (Europe)', '1994', 'Platformer', 'Traveller’s Tales', '1', 'Platformer', 'Side-scrolling platformer following Mickey''s career.', 'Journey through history, from Steamboat Willie to The Lonesome Ghosts.', 'A technical marvel with incredible Disney animation.', 'Mickey Mania features groundbreaking 16-bit visuals. Experience Mickey''s history across detailed and challenging stages in this definitive Sega classic.');
