INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mike-ditka-power-football-usa', 'Genesis', 'Mike Ditka Power Football (USA)', '1991', 'Sports', 'Beaucomm Interactive', '2', 'Sports', 'Top-down American football simulation.', 'Lead your team to victory through the playoffs.', 'A realistic football game featuring the legendary coach.', 'Mike Ditka Power Football offers a deep playbook and intense 16-bit action. Manage your strategy and dominate the field in this classic Sega sports title.');
