INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('minato-no-traysia-japan', 'Genesis', 'Minato no Traysia (Japan)', '1990', 'RPG', 'Telenet Japan', '1', 'Story-Driven', 'Traditional Japanese RPG with a focus on travel and story.', 'Escort Princess Traysia across a vast and dangerous land.', 'A colorful and story-driven Japanese RPG.', 'Minato no Traysia (Traysia) features classic 16-bit turn-based combat and a charming world. Discover secrets and build your party on the Mega Drive.');